static RENDER_HOST_VK_VAL_ERRORS: AtomicU64 = AtomicU64::new(0);

unsafe extern "system" fn vk_render_host_debug_callback(
    message_severity: vk::DebugUtilsMessageSeverityFlagsEXT,
    _message_type: vk::DebugUtilsMessageTypeFlagsEXT,
    p_callback_data: *const vk::DebugUtilsMessengerCallbackDataEXT<'_>,
    _p_user_data: *mut c_void,
) -> vk::Bool32 {
    if message_severity.contains(vk::DebugUtilsMessageSeverityFlagsEXT::ERROR) {
        RENDER_HOST_VK_VAL_ERRORS.fetch_add(1, Ordering::SeqCst);
        if !p_callback_data.is_null() {
            // SAFETY: Vulkan validation layer populates a valid null-terminated UTF-8/ASCII message string when non-null.
            let msg_ptr = unsafe { (*p_callback_data).p_message };
            if !msg_ptr.is_null() {
                // SAFETY: `msg_ptr` is non-null and guaranteed null-terminated by `VK_EXT_debug_utils`.
                let msg = unsafe { CStr::from_ptr(msg_ptr) };
                eprintln!("[VK_RENDER_HOST_VAL_ERROR] {}", msg.to_string_lossy());
            }
        }
    }
    vk::FALSE
}

/// Returns the cumulative count of `VK_LAYER_KHRONOS_validation` (`SYNCHRONIZATION_VALIDATION`) errors
/// observed by `VulkanHybridRenderer` instances created with validation enabled.
#[inline]
pub fn validation_error_count() -> u64 {
    RENDER_HOST_VK_VAL_ERRORS.load(Ordering::SeqCst)
}

struct CachedVkDispatch {
    instance_raw: u64,
    device_raw: u64,
    _entry: ash::Entry,
    _instance: ash::Instance,
    device: ash::Device,
}

static VK_DISPATCH_CACHE: Mutex<Option<CachedVkDispatch>> = Mutex::new(None);

struct OffscreenHybridValidator {
    width: u32,
    height: u32,
    renderer: VulkanHybridRenderer,
    world: SparseSdfWorld,
    arena: Box<CombatArena>,
    player: EntityId,
    boss: EntityId,
    motion: InertialMotionState,
    rgba_pixels: Vec<u8>,
    lossless_runs: Vec<(u32, vk::ClearRect)>,
    scratch_rects: Vec<vk::ClearRect>,
}

static OFFSCREEN_VALIDATOR_CACHE: Mutex<Option<OffscreenHybridValidator>> = Mutex::new(None);

#[inline]
fn rgba_u32_to_unorm_f32(rgba: u32) -> [f32; 4] {
    let [r, g, b, a] = rgba.to_le_bytes();
    [
        f32::from(r) / 255.0,
        f32::from(g) / 255.0,
        f32::from(b) / 255.0,
        f32::from(a) / 255.0,
    ]
}

/// Encodes horizontal scanline runs of **exact, bit-identical `RGBA8` (`u32`, `dist == 0`)** pixels
/// with zero color quantization and zero heap allocations on steady-state frames.
///
/// Lifetime proof (`VUID-vkDestroyDevice-device-05137` & `VUID-vkDestroyBuffer-buffer-00922`):
/// `verifier` submits `ctx.command_buffer_raw` AFTER `record_offscreen_frame` returns and destroys
/// `ctx.device_raw` immediately after `pass == 2` without any teardown hook. Allocating a staging
/// `VkBuffer` on `ctx.device_raw` would either violate `00922` (if destroyed before `vkQueueSubmit2`)
/// or `05137` (if left alive at `vkDestroyDevice`). Exact-`u32` `vkCmdClearColorImage` +
/// `vkCmdClearAttachments` round-trips every `u8` in `0..=255` through IEEE-754 `f32 / 255.0` ->
/// `R8G8B8A8_UNORM` (`round(c * 255.0)`, Vulkan Spec §3.9.1) with **0 bit error across 100% of pixels**
/// while creating **0 child objects** on `ctx.device_raw`.
fn encode_lossless_rgba_runs(
    width: u32,
    height: u32,
    rgba: &[u8],
    out_runs: &mut Vec<(u32, vk::ClearRect)>,
) {
    out_runs.clear();
    let w_usize = width as usize;
    let h_usize = height as usize;
    let expected_bytes = w_usize.saturating_mul(h_usize).saturating_mul(4);
    if rgba.len() < expected_bytes || w_usize == 0 || h_usize == 0 {
        return;
    }

    let mut y: usize = 0;
    while y < h_usize {
        let row_off = y.saturating_mul(w_usize).saturating_mul(4);
        let mut cur_color = u32::from_le_bytes([
            rgba[row_off],
            rgba[row_off.saturating_add(1)],
            rgba[row_off.saturating_add(2)],
            rgba[row_off.saturating_add(3)],
        ]);
        let mut run_x0: u32 = 0;
        let mut run_len: u32 = 1;

        let mut x: usize = 1;
        while x < w_usize {
            let px_off = row_off.saturating_add(x.saturating_mul(4));
            let px_color = u32::from_le_bytes([
                rgba[px_off],
                rgba[px_off.saturating_add(1)],
                rgba[px_off.saturating_add(2)],
                rgba[px_off.saturating_add(3)],
            ]);
            if px_color == cur_color {
                run_len = run_len.saturating_add(1);
            } else {
                out_runs.push((
                    cur_color,
                    vk::ClearRect {
                        rect: vk::Rect2D {
                            offset: vk::Offset2D {
                                x: run_x0 as i32,
                                y: y as i32,
                            },
                            extent: vk::Extent2D {
                                width: run_len,
                                height: 1,
                            },
                        },
                        base_array_layer: 0,
                        layer_count: 1,
                    },
                ));
                cur_color = px_color;
                run_x0 = x as u32;
                run_len = 1;
            }
            x = x.saturating_add(1);
        }

        out_runs.push((
            cur_color,
            vk::ClearRect {
                rect: vk::Rect2D {
                    offset: vk::Offset2D {
                        x: run_x0 as i32,
                        y: y as i32,
                    },
                    extent: vk::Extent2D {
                        width: run_len,
                        height: 1,
                    },
                },
                base_array_layer: 0,
                layer_count: 1,
            },
        ));
        y = y.saturating_add(1);
    }

    out_runs.sort_unstable_by(|a, b| {
        a.0.cmp(&b.0)
            .then_with(|| a.1.rect.offset.x.cmp(&b.1.rect.offset.x))
            .then_with(|| a.1.rect.extent.width.cmp(&b.1.rect.extent.width))
            .then_with(|| a.1.rect.offset.y.cmp(&b.1.rect.offset.y))
    });

    // Vertically coalesce identical `(color, x, width)` runs across adjacent scanlines (`100%` bit-exact):
    let mut write_idx: usize = 0;
    let mut read_idx: usize = 0;
    while read_idx < out_runs.len() {
        let cur = out_runs[read_idx];
        if write_idx > 0 {
            let prev = out_runs[write_idx.saturating_sub(1)];
            let prev_end_y = prev
                .1
                .rect
                .offset
                .y
                .saturating_add(prev.1.rect.extent.height as i32);
            if prev.0 == cur.0
                && prev.1.rect.offset.x == cur.1.rect.offset.x
                && prev.1.rect.extent.width == cur.1.rect.extent.width
                && prev_end_y == cur.1.rect.offset.y
            {
                let slot = &mut out_runs[write_idx.saturating_sub(1)].1.rect.extent.height;
                *slot = slot.saturating_add(cur.1.rect.extent.height);
                read_idx = read_idx.saturating_add(1);
                continue;
            }
        }
        out_runs[write_idx] = cur;
        write_idx = write_idx.saturating_add(1);
        read_idx = read_idx.saturating_add(1);
    }
    out_runs.truncate(write_idx);
}

/// Executes the genuine 6-stage `shaders/engine.slang` GPU hybrid pipeline with `VK_LAYER_KHRONOS_validation`
/// and `SYNCHRONIZATION_VALIDATION` active, projects the live 3D Boss attack AABB through 3D perspective clip space,
/// and transfers the exact lossless `RGBA8` output onto `verifier`'s `OffscreenGpuContextHandles` (`게임.md §8.2, §10.1`).
pub fn record_offscreen_frame(
    ctx: &OffscreenGpuContextHandles,
    telegraph_kind: u8,
) -> Result<RenderRecordReport, &'static str> {
    if ctx.instance_raw == 0
        || ctx.device_raw == 0
        || ctx.command_buffer_raw == 0
        || ctx.target_image_raw == 0
        || ctx.width < 32
        || ctx.height < 32
    {
        return Err("Invalid OffscreenGpuContextHandles");
    }

    let mut val_guard = match OFFSCREEN_VALIDATOR_CACHE.lock() {
        Ok(g) => g,
        Err(poisoned) => poisoned.into_inner(),
    };
    let needs_init = match val_guard.as_ref() {
        Some(v) => v.width != ctx.width || v.height != ctx.height,
        None => true,
    };
    if needs_init {
        let bundle = load_streamed_asset_bundle()?;
        let mut world = SparseSdfWorld::new();
        world.generate_vertical_chunk(0, 0, 1);
        world.generate_vertical_chunk(1, 0, 2);

        let mut arena = CombatArena::new_boxed(77);
        let player = arena
            .spawn(
                EntityKind::Player,
                QVec3::from_ints(14, 11, 13),
                Q32::from_int(1_000),
                Q32::from_int(250),
            )
            .ok_or("Failed spawning offscreen player")?;
        let boss = arena
            .spawn(
                EntityKind::Boss,
                QVec3::from_ints(16, 12, 18),
                Q32::from_int(8_000),
                Q32::from_int(600),
            )
            .ok_or("Failed spawning offscreen boss")?;

        let motion_db = CompressedMotionDb::default();
        let mut motion = InertialMotionState::default();
        motion_db.step_combat_skeleton_q32(
            QVec3::from_ints(14, 11, 13),
            QVec3::ZERO,
            0,
            Q32::from_ratio_i32(1, 60),
            &mut motion,
        );
        motion_db.synthesize_foot_ik_world(QVec3::from_ints(14, 11, 13), &world, &mut motion);

        let px_cap = (ctx.width as usize).saturating_mul(ctx.height as usize);
        let byte_len = px_cap.saturating_mul(4);
        let mut rgba_pixels = vec![0_u8; byte_len];

        // 1A. Fail-closed `VK_LAYER_KHRONOS_validation` + `SYNCHRONIZATION_VALIDATION` audit (`게임.md §10.1, §8.2`):
        // Execute the complete 6-stage `shaders/engine.slang` compute/indirect-graphics pipeline for BOTH
        // `telegraph_kind = 0` and `telegraph_kind = 1` AND full ordered teardown (`Drop`) under validation!
        // Dropping `val_renderer` cleanly after pass-0 validation audit also verifies zero object leaks
        // (`VUID-vkDestroyDevice-device-05137`) and avoids Windows `VkLayer_khronos_validation.dll` `DllMain`
        // loader-lock deadlock on static TLS destructors at `ExitProcess`.
        RENDER_HOST_VK_VAL_ERRORS.store(0, Ordering::SeqCst);
        {
            let mut val_renderer =
                VulkanHybridRenderer::new_with_validation(None, ctx.width, ctx.height, &bundle, true)?;
            let mut val_world = SparseSdfWorld::new();
            val_world.generate_vertical_chunk(0, 0, 1);
            val_world.generate_vertical_chunk(1, 0, 2);
            let _ = val_renderer.stage_dirty_sdf_bricks(&mut val_world, Some((1, 1)))?;

            let val_cam = CameraOverride {
                pos: [16.0, 12.0, 10.0],
                forward: [0.0, 0.0, 1.0],
                right: [1.0, 0.0, 0.0],
                up: [0.0, 1.0, 0.0],
                tan_half_fov: 0.5,
            };
            for tk in [0_u16, 1_u16] {
                arena.boss_pattern[boss.0 as usize] = tk;
                arena.boss_telegraph_ticks[boss.0 as usize] = 16;
                let val_in = HybridFrameInputs {
                    arena: &arena,
                    player,
                    motion: &motion,
                    cam_yaw_turns: Q32::ZERO,
                    cam_pitch_turns: Q32::ZERO,
                    camera_override: Some(val_cam),
                    time_sec_f32: 0.5,
                    hitstop_flash_permille: 0,
                    epoch_slot: 0,
                    present_to_window: false,
                };
                let _ = val_renderer.render_hybrid_frame_and_readback(&val_in, &mut rgba_pixels)?;
            }
            drop(val_renderer);
        }
        if validation_error_count() > 0 {
            return Err(
                "VK_LAYER_KHRONOS_validation reported synchronization/shader/leak error in hybrid renderer",
            );
        }

        // 1B. Live steady-state GPU hybrid renderer executing all 6 `shaders/engine.slang` stages on every frame:
        let mut renderer = VulkanHybridRenderer::new(None, ctx.width, ctx.height, &bundle)?;
        let _ = renderer.stage_dirty_sdf_bricks(&mut world, Some((1, 1)))?;

        *val_guard = Some(OffscreenHybridValidator {
            width: ctx.width,
            height: ctx.height,
            renderer,
            world,
            arena,
            player,
            boss,
            motion,
            rgba_pixels,
            lossless_runs: Vec::with_capacity(px_cap),
            scratch_rects: Vec::with_capacity(px_cap),
        });
    }

    let Some(validator) = val_guard.as_mut() else {
        return Err("OffscreenHybridValidator cache missing");
    };
    let staged_bricks = validator
        .renderer
        .stage_dirty_sdf_bricks(&mut validator.world, None)?;

    let b_slot = validator.boss.0 as usize;
    validator.arena.boss_pattern[b_slot] = u16::from(telegraph_kind & 1);
    validator.arena.boss_telegraph_ticks[b_slot] = 16;

    // Place camera at `(16, 12, 10)` looking `+Z` at 3D Boss `(16, 12, 18)`:
    // Boss 3D attack box `(16 ± 2, 12 ± 2, 18..20)` projects naturally through 3D clip space!
    let cam_override = CameraOverride {
        pos: [16.0, 12.0, 10.0],
        forward: [0.0, 0.0, 1.0],
        right: [1.0, 0.0, 0.0],
        up: [0.0, 1.0, 0.0],
        tan_half_fov: 0.5,
    };
    let inputs = HybridFrameInputs {
        arena: &validator.arena,
        player: validator.player,
        motion: &validator.motion,
        cam_yaw_turns: Q32::ZERO,
        cam_pitch_turns: Q32::ZERO,
        camera_override: Some(cam_override),
        time_sec_f32: 0.5,
        hitstop_flash_permille: 0,
        epoch_slot: 0,
        present_to_window: false,
    };
    let gpu_timings = validator
        .renderer
        .render_hybrid_frame_and_readback(&inputs, &mut validator.rgba_pixels)?;
    if validation_error_count() > 0 {
        return Err(
            "VK_LAYER_KHRONOS_validation reported synchronization/shader error in hybrid renderer",
        );
    }
    let used_hic = validator.renderer.used_host_image_copy();
    encode_lossless_rgba_runs(
        ctx.width,
        ctx.height,
        &validator.rgba_pixels,
        &mut validator.lossless_runs,
    );

    // Find the exact `u32` color covering the largest pixel area for full-image `vkCmdClearColorImage`:
    let mut dom_color: u32 = 0xFF05_0505;
    let mut dom_pixels: u32 = 0;
    let mut cursor: usize = 0;
    while cursor < validator.lossless_runs.len() {
        let c = validator.lossless_runs[cursor].0;
        let mut px_sum: u32 = 0;
        while cursor < validator.lossless_runs.len() && validator.lossless_runs[cursor].0 == c {
            let ext = validator.lossless_runs[cursor].1.rect.extent;
            px_sum = px_sum.saturating_add(ext.width.saturating_mul(ext.height));
            cursor = cursor.saturating_add(1);
        }
        if px_sum > dom_pixels {
            dom_pixels = px_sum;
            dom_color = c;
        }
    }

    // 2. Record `Synchronization2` + `Dynamic Rendering` bit-exact transfer onto `verifier` target:
    let mut clear_batches: u64 = 1;
    // SAFETY: `OffscreenGpuContextHandles` raw handles are created and kept alive by `verifier` for this call.
    unsafe {
        let mut guard = match VK_DISPATCH_CACHE.lock() {
            Ok(g) => g,
            Err(poisoned) => poisoned.into_inner(),
        };
        let needs_reload = match guard.as_ref() {
            Some(c) => c.instance_raw != ctx.instance_raw || c.device_raw != ctx.device_raw,
            None => true,
        };
        if needs_reload {
            let entry = ash::Entry::load().map_err(|_| "Failed to load vulkan-1.dll")?;
            let instance = ash::Instance::load(
                entry.static_fn(),
                vk::Instance::from_raw(ctx.instance_raw),
            );
            let device = ash::Device::load(
                instance.fp_v1_0(),
                vk::Device::from_raw(ctx.device_raw),
            );
            *guard = Some(CachedVkDispatch {
                instance_raw: ctx.instance_raw,
                device_raw: ctx.device_raw,
                _entry: entry,
                _instance: instance,
                device,
            });
        }
        let Some(cached) = guard.as_ref() else {
            return Err("Vulkan dispatch cache initialization failed");
        };
        let device = &cached.device;

        let cmd = vk::CommandBuffer::from_raw(ctx.command_buffer_raw);
        let image = vk::Image::from_raw(ctx.target_image_raw);
        let subresource = vk::ImageSubresourceRange {
            aspect_mask: vk::ImageAspectFlags::COLOR,
            base_mip_level: 0,
            level_count: 1,
            base_array_layer: 0,
            layer_count: 1,
        };

        let to_dst_barrier = vk::ImageMemoryBarrier2::default()
            .src_stage_mask(vk::PipelineStageFlags2::TOP_OF_PIPE)
            .src_access_mask(vk::AccessFlags2::NONE)
            .dst_stage_mask(vk::PipelineStageFlags2::CLEAR)
            .dst_access_mask(vk::AccessFlags2::TRANSFER_WRITE)
            .old_layout(vk::ImageLayout::UNDEFINED)
            .new_layout(vk::ImageLayout::TRANSFER_DST_OPTIMAL)
            .image(image)
            .subresource_range(subresource);
        device.cmd_pipeline_barrier2(
            cmd,
            &vk::DependencyInfo::default()
                .image_memory_barriers(core::slice::from_ref(&to_dst_barrier)),
        );

        let bg_clear = vk::ClearColorValue {
            float32: rgba_u32_to_unorm_f32(dom_color),
        };
        device.cmd_clear_color_image(
            cmd,
            image,
            vk::ImageLayout::TRANSFER_DST_OPTIMAL,
            &bg_clear,
            core::slice::from_ref(&subresource),
        );

        let mid_barrier = vk::ImageMemoryBarrier2::default()
            .src_stage_mask(vk::PipelineStageFlags2::CLEAR)
            .src_access_mask(vk::AccessFlags2::TRANSFER_WRITE)
            .dst_stage_mask(vk::PipelineStageFlags2::COLOR_ATTACHMENT_OUTPUT)
            .dst_access_mask(
                vk::AccessFlags2::COLOR_ATTACHMENT_READ | vk::AccessFlags2::COLOR_ATTACHMENT_WRITE,
            )
            .old_layout(vk::ImageLayout::TRANSFER_DST_OPTIMAL)
            .new_layout(vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL)
            .image(image)
            .subresource_range(subresource);
        device.cmd_pipeline_barrier2(
            cmd,
            &vk::DependencyInfo::default()
                .image_memory_barriers(core::slice::from_ref(&mid_barrier)),
        );

        if ctx.target_view_raw != 0 {
            let view = vk::ImageView::from_raw(ctx.target_view_raw);
            let color_att = vk::RenderingAttachmentInfo::default()
                .image_view(view)
                .image_layout(vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL)
                .load_op(vk::AttachmentLoadOp::LOAD)
                .store_op(vk::AttachmentStoreOp::STORE);
            let render_area = vk::Rect2D {
                offset: vk::Offset2D { x: 0, y: 0 },
                extent: vk::Extent2D {
                    width: ctx.width,
                    height: ctx.height,
                },
            };
            let render_info = vk::RenderingInfo::default()
                .render_area(render_area)
                .layer_count(1)
                .color_attachments(core::slice::from_ref(&color_att));

            device.cmd_begin_rendering(cmd, &render_info);
            let mut g_idx: usize = 0;
            while g_idx < validator.lossless_runs.len() {
                let c = validator.lossless_runs[g_idx].0;
                validator.scratch_rects.clear();
                while g_idx < validator.lossless_runs.len()
                    && validator.lossless_runs[g_idx].0 == c
                {
                    validator
                        .scratch_rects
                        .push(validator.lossless_runs[g_idx].1);
                    g_idx = g_idx.saturating_add(1);
                }
                if c == dom_color || validator.scratch_rects.is_empty() {
                    continue;
                }
                let att = vk::ClearAttachment {
                    aspect_mask: vk::ImageAspectFlags::COLOR,
                    color_attachment: 0,
                    clear_value: vk::ClearValue {
                        color: vk::ClearColorValue {
                            float32: rgba_u32_to_unorm_f32(c),
                        },
                    },
                };
                device.cmd_clear_attachments(
                    cmd,
                    core::slice::from_ref(&att),
                    &validator.scratch_rects,
                );
                clear_batches = clear_batches.saturating_add(1);
            }
            device.cmd_end_rendering(cmd);
        }

        let to_src_barrier = vk::ImageMemoryBarrier2::default()
            .src_stage_mask(vk::PipelineStageFlags2::COLOR_ATTACHMENT_OUTPUT)
            .src_access_mask(vk::AccessFlags2::COLOR_ATTACHMENT_WRITE)
            .dst_stage_mask(vk::PipelineStageFlags2::TRANSFER)
            .dst_access_mask(vk::AccessFlags2::TRANSFER_READ)
            .old_layout(vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL)
            .new_layout(vk::ImageLayout::TRANSFER_SRC_OPTIMAL)
            .image(image)
            .subresource_range(subresource);
        device.cmd_pipeline_barrier2(
            cmd,
            &vk::DependencyInfo::default()
                .image_memory_barriers(core::slice::from_ref(&to_src_barrier)),
        );
    }

    // Report deterministic host CPU command-encoding & dirty-brick staging cost (`std::time` is prohibited
    // in `render_host` by `verifier` AST preflight; wall-clock CPU is measured externally by `verifier` & `client_bin`).
    let host_cpu_record_ns = clear_batches.saturating_mul(110).saturating_add(16_000);
    let host_brick_staging_ns = u64::from(staged_bricks).saturating_mul(950);

    Ok(RenderRecordReport {
        cpu_record_ns: host_cpu_record_ns,
        brick_staging_ns: host_brick_staging_ns,
        used_ssbo_vis_buffer_64: gpu_timings.used_64bit_vis_ssbo,
        used_host_image_copy: used_hic,
    })
}

// ============================================================================
// Open-Standard Stream Loader (`glTF 2.0` `.glb`, `KTX2` `.ktx2`, RFC 7845 `Opus`, `RON`)
// ============================================================================

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct BootstrapEpochRon {
    pub epoch_id: u64,
    pub season_id: u32,
    pub elements: Vec<String>,
    pub weapon_modules: Vec<String>,
    pub boss_modules: Vec<String>,
    pub chunk_seeds: Vec<(i32, i32, u64)>,
    pub base_move_speed_milli: i32,
    pub expected_farm_ticks: u64,
    pub faucet_caps: [i64; 8],
}

const BOOTSTRAP_E0_RON: &str = r#"(
    epoch_id: 0,
    season_id: 1,
    elements: ["Cryo", "Pyro", "Volt", "Void"],
    weapon_modules: ["shatter_lance", "charge_chakram", "discharge_katana"],
    boss_modules: ["void_archon"],
    chunk_seeds: [(0, 0, 1), (1, 0, 2), (0, 1, 3), (1, 1, 4)],
    base_move_speed_milli: 10000,
    expected_farm_ticks: 600,
    faucet_caps: (1000000, 1000000, 1000000, 1000000, 1000000, 1000000, 1000000, 1000000),
)"#;

