pub struct StreamedAssetBundle {
    pub meshlets: Vec<MeshletGpu>,
    pub vertices: Vec<[f32; 4]>,
    pub indices: Vec<u32>,
    pub skeleton_joint_count: usize,
    pub rest_joint_offsets: [[f32; 3]; 6],
    pub cel_lut_texels: [u32; 16],
    pub cel_lut_mips: Vec<Ktx2MipLevel>,
    pub opus_bytes: Vec<u8>,
    pub pinned_epoch: EpochHandle<Pinned>,
    pub chunk_seeds: Vec<(i32, i32, u64)>,
}

/// Streams open-standard `glTF 2.0` (`.glb` with multi-bone `JOINTS_0` + `inverseBindMatrices`),
/// mipmapped `KTX2` (`.ktx2`), RFC 7845 `Ogg Opus` (`.opus`), and `RON` (`E_0.ron`) from `assets/`
/// when present, or falls back seamlessly to the embedded open-standard bootstrap bundle (`게임.md §5.1, §7.1`).
pub fn load_streamed_asset_bundle() -> Result<StreamedAssetBundle, &'static str> {
    let glb_cow: Vec<u8> = match fs::read(Path::new("assets/meshes/simulacrum_rig.glb")) {
        Ok(b) if !b.is_empty() => b,
        _ => BOOTSTRAP_GLB_BYTES.to_vec(),
    };
    let ktx_cow: Vec<u8> = match fs::read(Path::new("assets/textures/cel_lut.ktx2")) {
        Ok(b) if !b.is_empty() => b,
        _ => BOOTSTRAP_KTX2_BYTES.to_vec(),
    };
    let opus_bytes: Vec<u8> = match fs::read(Path::new("assets/audio/combat_sfx.opus")) {
        Ok(b) if b.len() >= 28 && &b[0..4] == b"OggS" => b,
        _ => BOOTSTRAP_OPUS_STREAM_BYTES.to_vec(),
    };
    let ron_str: String = match fs::read_to_string(Path::new("assets/manifests/E_0.ron")) {
        Ok(s) if !s.is_empty() => s,
        _ => BOOTSTRAP_E0_RON.to_string(),
    };

    // 1. Parse `glTF 2.0` binary mesh, multi-bone `JOINTS_0`, and `inverseBindMatrices`:
    let parsed_gltf = gltf::Gltf::from_slice(&glb_cow).map_err(|_| "Invalid glTF 2.0 .glb stream")?;
    let blob = parsed_gltf.blob.as_deref().ok_or("glTF .glb missing BIN chunk")?;

    let mut rest_joint_offsets = [
        [0.0_f32, 0.90, 0.0],
        [0.0_f32, 1.45, 0.0],
        [0.45_f32, 1.25, 0.20],
        [-0.42_f32, 1.20, 0.10],
        [-0.18_f32, 0.00, 0.0],
        [0.18_f32, 0.00, 0.0],
    ];
    let mut joint_count: usize = 6;
    if let Some(skin) = parsed_gltf.skins().next() {
        joint_count = skin.joints().count().max(1);
        let skin_reader = skin.reader(|_buf| Some(blob));
        if let Some(ibm_iter) = skin_reader.read_inverse_bind_matrices() {
            for (ji, mat) in ibm_iter.take(6).enumerate() {
                rest_joint_offsets[ji] = [-mat[3][0], -mat[3][1], -mat[3][2]];
            }
        }
    }

    let mesh = parsed_gltf.meshes().next().ok_or("glTF .glb contains zero meshes")?;
    let prim = mesh.primitives().next().ok_or("glTF mesh contains zero primitives")?;
    let reader = prim.reader(|_buf| Some(blob));

    let positions: Vec<[f32; 3]> = reader
        .read_positions()
        .ok_or("glTF primitive missing POSITION")?
        .collect();
    let _normals: Vec<[f32; 3]> = match reader.read_normals() {
        Some(it) => it.collect(),
        None => vec![[0.0, 1.0, 0.0]; positions.len()],
    };
    let joint_indices: Vec<[u16; 4]> = match reader.read_joints(0) {
        Some(j_it) => j_it.into_u16().collect(),
        None => vec![[0, 0, 0, 0]; positions.len()],
    };
    let raw_indices: Vec<u32> = reader
        .read_indices()
        .ok_or("glTF primitive missing indices")?
        .into_u32()
        .collect();

    if positions.is_empty()
        || positions.len() > 64
        || raw_indices.len() < 3
        || raw_indices.len().checked_div(3).unwrap_or(125) > 124
    {
        return Err("glTF bootstrap meshlet exceeds <=64 verts / <=124 tris cluster bound");
    }

    // Pack per-vertex joint index `((bone_idx & 0xFF) << 8) | 1` into `vertex[3]` for multi-bone Player skinning:
    let mut vertices = Vec::with_capacity(positions.len().saturating_mul(3));
    for (vi, p) in positions.iter().enumerate() {
        let j0 = joint_indices.get(vi).map(|j| j[0]).unwrap_or(0);
        let packed_meta = ((u32::from(j0) & 0xFF) << 8) | 1_u32;
        vertices.push([p[0], p[1], p[2], packed_meta as f32]);
    }
    let base_v_count = positions.len() as u32;
    let base_tri_count = raw_indices.len().checked_div(3).unwrap_or(1) as u32;

    // Duplicate scaled Boss & Boss-Shield-Fracture cluster geometry (`hasPerVertBone = 0` -> uses `rootBone = 6, 7`):
    for scale in [2.2_f32, 1.35_f32] {
        for p in &positions {
            vertices.push([p[0] * scale, p[1] * scale, p[2] * scale, 0.0]);
        }
    }
    let mut indices = Vec::with_capacity(raw_indices.len().saturating_mul(3));
    for _cluster in 0..3 {
        indices.extend_from_slice(&raw_indices);
    }

    let idx_stride = raw_indices.len() as u32;
    let meshlets = vec![
        // Cluster 0: Player Simulacrum (`bones 0..5` per-vertex multi-bone DQ skinning, cyan-silver armor)
        MeshletGpu {
            bounding_sphere: [0.0, 0.9, 0.0, 1.9],
            cone_axis_cutoff: [0.0, 0.0, 1.0, 1.0],
            counts_and_offs: [base_v_count, base_tri_count, 0, 0],
            material_params: [0x00F4_D878, 280, 150, 0],
        },
        // Cluster 1: Adaptive Multi-Phase Boss Core (`bone 6`, crimson-obsidian carapace)
        MeshletGpu {
            bounding_sphere: [0.0, 2.0, 0.0, 4.2],
            cone_axis_cutoff: [0.0, 0.0, 1.0, 1.0],
            counts_and_offs: [base_v_count, base_tri_count, base_v_count, idx_stride],
            material_params: [0x0052_34DC, 220, 400, 6],
        },
        // Cluster 2: Boss Real-Time Fracturable Crest (`bone 7`, golden aether core)
        MeshletGpu {
            bounding_sphere: [0.0, 2.6, 0.0, 2.8],
            cone_axis_cutoff: [0.0, 0.0, 1.0, 1.0],
            counts_and_offs: [
                base_v_count,
                base_tri_count,
                base_v_count.saturating_mul(2),
                idx_stride.saturating_mul(2),
            ],
            material_params: [0x0048_D4FF, 140, 800, 7],
        },
    ];

    // 2. Parse mipmapped `KTX 2.0` texture (`R8G8B8A8_UNORM` cel-shading ramp LUT):
    let ktx_reader = ktx2::Reader::new(&ktx_cow).map_err(|_| "Invalid KTX2 stream")?;
    let hdr = ktx_reader.header();
    if hdr.format != Some(ktx2::Format::R8G8B8A8_UNORM) || hdr.pixel_width < 16 {
        return Err("KTX2 cel LUT must be R8G8B8A8_UNORM width >= 16");
    }
    let base_w = hdr.pixel_width.max(1);
    let base_h = hdr.pixel_height.max(1);
    let mut cel_lut_mips: Vec<Ktx2MipLevel> = Vec::new();
    for (mip_idx, lvl) in ktx_reader.levels().enumerate() {
        let mw = (base_w >> (mip_idx.min(16) as u32)).max(1);
        let mh = (base_h >> (mip_idx.min(16) as u32)).max(1);
        let needed = (mw as usize).saturating_mul(mh as usize).saturating_mul(4);
        if lvl.data.len() >= needed {
            cel_lut_mips.push(Ktx2MipLevel {
                width: mw,
                height: mh,
                rgba_bytes: lvl.data[..needed].to_vec(),
            });
        }
    }
    let Some(level0) = cel_lut_mips.first() else {
        return Err("KTX2 stream missing mip level 0");
    };
    if level0.rgba_bytes.len() < 64 {
        return Err("KTX2 mip level 0 truncated");
    }
    let mut cel_lut_texels = [0_u32; 16];
    let mut ti: usize = 0;
    while ti < 16 {
        let base = ti.saturating_mul(4);
        cel_lut_texels[ti] = u32::from_le_bytes([
            level0.rgba_bytes[base],
            level0.rgba_bytes[base.saturating_add(1)],
            level0.rgba_bytes[base.saturating_add(2)],
            level0.rgba_bytes[base.saturating_add(3)],
        ]);
        ti = ti.saturating_add(1);
    }

    // 3. Parse `RON` epoch manifest & seal into Typestate `EpochHandle<Pinned>`:
    let parsed_ron: BootstrapEpochRon =
        ron::from_str(&ron_str).map_err(|_| "Invalid bootstrap E_0.ron manifest")?;
    let summary = EpochManifestSummary {
        epoch_id: parsed_ron.epoch_id,
        season_id: parsed_ron.season_id,
        merkle_root: [0; 32],
        faucet_caps: parsed_ron.faucet_caps,
        base_move_speed_q32: Q32::from_ratio_i32(parsed_ron.base_move_speed_milli, 1_000),
        expected_farm_ticks: parsed_ron.expected_farm_ticks,
        synth_clear_permille: 500,
        synth_exit_mean_permille: 20,
        synth_exit_std_permille: 10,
    };
    let pinned_epoch = EpochHandle::<Staging>::new_staging(summary).seal_and_pin();

    Ok(StreamedAssetBundle {
        meshlets,
        vertices,
        indices,
        skeleton_joint_count: joint_count,
        rest_joint_offsets,
        cel_lut_texels,
        cel_lut_mips,
        opus_bytes,
        pinned_epoch,
        chunk_seeds: parsed_ron.chunk_seeds,
    })
}

/// Streams the active 3-weapon loadout `.qvm` scripts (`prelude.qvm` + 3 weapon stems from `E_1.ron`)
/// from `gameplay/` when present on disk (`None` when running as a standalone portable `.exe`).
pub fn try_load_active_weapon_qvm_sources() -> Option<[String; 3]> {
    let prelude = fs::read_to_string(Path::new("gameplay/prelude.qvm")).ok()?;
    let e1_raw = fs::read_to_string(Path::new("assets/manifests/E_1.ron")).ok()?;
    let parsed_e1: BootstrapEpochRon = ron::from_str(&e1_raw).ok()?;
    if parsed_e1.weapon_modules.len() < 3 {
        return None;
    }
    let load_slot = |idx: usize| -> Option<String> {
        let stem = parsed_e1.weapon_modules.get(idx)?;
        let rel = format!("gameplay/weapons/{stem}.qvm");
        let body = fs::read_to_string(Path::new(&rel)).ok()?;
        Some(format!("{prelude}\n{body}"))
    };
    Some([load_slot(0)?, load_slot(1)?, load_slot(2)?])
}

/// Streams Season `E_1` multi-axis resonance trait (`gameplay/traits/e1_*.qvm`) and 3-tier
/// `Silver -> Gold -> Prism` gate tactical augment (`gameplay/augments/e1_*.qvm`) sources, each prefixed
/// with `prelude.qvm`, in deterministic lexicographic order (`None` when running as a standalone `.exe`).
pub fn try_load_season_trait_and_augment_qvm_sources() -> Option<(Vec<String>, Vec<String>)> {
    let prelude = fs::read_to_string(Path::new("gameplay/prelude.qvm")).ok()?;
    let load_dir = |dir: &str| -> Option<Vec<String>> {
        let mut paths: Vec<std::path::PathBuf> = fs::read_dir(Path::new(dir))
            .ok()?
            .filter_map(|e| e.ok().map(|d| d.path()))
            .filter(|p| {
                p.extension().is_some_and(|x| x == "qvm")
                    && p
                        .file_name()
                        .is_some_and(|n| n.to_string_lossy().starts_with("e1_"))
            })
            .collect();
        paths.sort();
        let mut out = Vec::with_capacity(paths.len());
        for p in paths {
            let body = fs::read_to_string(&p).ok()?;
            out.push(format!("{prelude}\n{body}"));
        }
        Some(out)
    };
    let traits = load_dir("gameplay/traits")?;
    let augments = load_dir("gameplay/augments")?;
    if traits.len() < 3 || augments.len() < 3 {
        return None;
    }
    Some((traits, augments))
}

// ============================================================================
// SPIR-V `OpCapability` Static Gate (`게임.md §8.2`)
// ============================================================================

#[derive(Clone, Copy, Debug)]
pub struct HardwareVulkanCaps {
    pub vulkan_minor: u32,
    pub shader_int64: bool,
    pub shader_int64_atomics: bool,
    pub buffer_device_address: bool,
    pub host_image_copy: bool,
    pub draw_parameters: bool,
    pub draw_indirect_count: bool,
    pub fragment_stores_and_atomics: bool,
    pub sampled_image_non_uniform: bool,
    pub dynamic_rendering_local_read: bool,
    pub maintenance5: bool,
    pub graphics_pipeline_library: bool,
    pub present_wait: bool,
    pub ray_query: bool,
    pub mesh_shader: bool,
}

/// Inspects raw SPIR-V `u32` words before `vkCreateShaderModule` and blocks any unsupported `OpCapability`.
pub fn verify_spirv_capabilities(words: &[u32], caps: &HardwareVulkanCaps) -> Result<(), &'static str> {
    if words.len() < 5 || words[0] != 0x0723_0203 {
        return Err("Invalid SPIR-V magic header");
    }
    let mut pos: usize = 5;
    while pos < words.len() {
        let header = words[pos];
        let word_count = (header >> 16) as usize;
        let opcode = header & 0xFFFF;
        if word_count == 0 || pos.saturating_add(word_count) > words.len() {
            return Err("Malformed SPIR-V instruction stream");
        }
        // OpCapability == 17
        if opcode == 17 && word_count >= 2 {
            let cap_id = words[pos.saturating_add(1)];
            match cap_id {
                0 | 1 => {} // Matrix, Shader (Vulkan 1.0 core)
                11 if caps.shader_int64 => {} // Int64
                12 if caps.shader_int64_atomics => {} // Int64Atomics
                4427 if caps.draw_parameters => {} // DrawParameters
                5301 | 5307 if caps.sampled_image_non_uniform => {} // ShaderNonUniform, SampledImageArrayNonUniformIndexing
                5347 if caps.buffer_device_address => {} // PhysicalStorageBufferAddresses
                _ => return Err("Blocked unsupported SPIR-V OpCapability on current GPU"),
            }
        }
        // Stop header scan once past OpFunction (54)
        if opcode == 54 {
            break;
        }
        pos = pos.saturating_add(word_count);
    }
    Ok(())
}

