struct GpuBufferSlot {
    buffer: vk::Buffer,
    allocation: Option<Allocation>,
    device_address: u64,
}

struct GpuImageSlot {
    image: vk::Image,
    view: vk::ImageView,
    allocation: Option<Allocation>,
}

/// Immutable compiled pipeline bundle managed via `ArcSwap` for `0ms` background worker-thread PSO hot-swap (`게임.md §5.2, §8.2`).
struct CompiledPsoSet {
    device: ash::Device,
    use_64bit_vis_ssbo: bool,
    sdf_world_pso: vk::Pipeline,
    meshlet_cull_vis_pso: vk::Pipeline,
    vis_indirect_gfx_pso: vk::Pipeline,
    meshlet_cel_pso: vk::Pipeline,
    radiance_cascades_pso: vk::Pipeline,
    vfx_telegraph_pso: vk::Pipeline,
    vis_fallback_gfx_pso: vk::Pipeline,
    tile_shade_fallback_pso: vk::Pipeline,
}

impl Drop for CompiledPsoSet {
    fn drop(&mut self) {
        // SAFETY: Pipelines are owned exclusively by this reference-counted `CompiledPsoSet`
        // and destroyed only after `Timeline Semaphore` retirement & `Arc` strong count == 0.
        unsafe {
            for pso in [
                self.sdf_world_pso,
                self.meshlet_cull_vis_pso,
                self.vis_indirect_gfx_pso,
                self.meshlet_cel_pso,
                self.radiance_cascades_pso,
                self.vfx_telegraph_pso,
                self.vis_fallback_gfx_pso,
                self.tile_shade_fallback_pso,
            ] {
                if pso != vk::Pipeline::null() {
                    self.device.destroy_pipeline(pso, None);
                }
            }
        }
    }
}

struct RetiredPsoEntry {
    retire_after_timeline: u64,
    _pso_set: Arc<CompiledPsoSet>,
}

struct PsoWorkerSuccess {
    pso_set: CompiledPsoSet,
    worker_cache: vk::PipelineCache,
}

struct SwapchainPresenter {
    surface_loader: ash::khr::surface::Instance,
    swapchain_loader: ash::khr::swapchain::Device,
    present_wait_loader: Option<ash::khr::present_wait::Device>,
    surface: vk::SurfaceKHR,
    swapchain: vk::SwapchainKHR,
    images: Vec<vk::Image>,
    views: Vec<vk::ImageView>,
    extent: vk::Extent2D,
    acquire_sem: vk::Semaphore,
    present_sem: vk::Semaphore,
    present_serial: u64,
}

