pub const MAX_GPU_BRICKS: usize = 320;
const BONE_PALETTE_CAP: usize = 16;
const MAX_INDIRECT_CLUSTERS: usize = 4096;
const BINDLESS_TEXTURE_SLOTS: u32 = 16;

/// Projects all 8 corners of a 3D world-space Boss telegraph volume `[center ± half_ext]`
/// through the active 3D camera frustum (`projectWorldToClip`) into screen pixel `[x0, y0, w0, h0]`.
fn project_boss_telegraph_aabb(
    boss_pos: [f32; 3],
    cam: &CameraOverride,
    aspect: f32,
    viewport: (u32, u32),
) -> Option<[u32; 4]> {
    let (width, height) = viewport;
    let denom_x = (aspect * cam.tan_half_fov).max(1e-4);
    let denom_y = cam.tan_half_fov.max(1e-4);
    let w_f = width as f32;
    let h_f = height as f32;

    let mut min_sx = f32::INFINITY;
    let mut min_sy = f32::INFINITY;
    let mut max_sx = f32::NEG_INFINITY;
    let mut max_sy = f32::NEG_INFINITY;
    let mut any_in_front = false;

    for dx in [-2.0_f32, 2.0_f32] {
        for dy in [-2.0_f32, 2.0_f32] {
            for dz in [0.0_f32, 2.0_f32] {
                let wx = boss_pos[0] + dx;
                let wy = boss_pos[1] + dy;
                let wz = boss_pos[2] + dz;
                let rx = wx - cam.pos[0];
                let ry = wy - cam.pos[1];
                let rz = wz - cam.pos[2];

                let vz = rx * cam.forward[0] + ry * cam.forward[1] + rz * cam.forward[2];
                if vz <= 0.25 {
                    continue;
                }
                any_in_front = true;
                let ndc_x = (rx * cam.right[0] + ry * cam.right[1] + rz * cam.right[2]) / (vz * denom_x);
                let ndc_y = -(rx * cam.up[0] + ry * cam.up[1] + rz * cam.up[2]) / (vz * denom_y);

                let sx = (ndc_x * 0.5 + 0.5) * w_f;
                let sy = (ndc_y * 0.5 + 0.5) * h_f;
                min_sx = min_sx.min(sx);
                min_sy = min_sy.min(sy);
                max_sx = max_sx.max(sx);
                max_sy = max_sy.max(sy);
            }
        }
    }

    if !any_in_front || max_sx <= 0.0 || max_sy <= 0.0 || min_sx >= w_f || min_sy >= h_f {
        return None;
    }

    let x0 = (min_sx.round().clamp(0.0, (width.saturating_sub(16)) as f32)) as u32;
    let y0 = (min_sy.round().clamp(0.0, (height.saturating_sub(16)) as f32)) as u32;
    let x1 = (max_sx.round().clamp(16.0, w_f)) as u32;
    let y1 = (max_sy.round().clamp(16.0, h_f)) as u32;
    let w0 = x1.saturating_sub(x0).clamp(16, width.saturating_sub(x0).max(16));
    let h0 = y1.saturating_sub(y0).clamp(16, height.saturating_sub(y0).max(16));
    Some([x0, y0, w0, h0])
}

pub struct VulkanHybridRenderer {
    _entry: ash::Entry,
    instance: ash::Instance,
    debug_utils: Option<(ash::ext::debug_utils::Instance, vk::DebugUtilsMessengerEXT)>,
    device: ash::Device,
    queue: vk::Queue,
    caps: HardwareVulkanCaps,
    used_hic_upload: bool,
    timestamp_period_ns: f64,
    width: u32,
    height: u32,
    rest_joint_offsets: [[f32; 3]; 6],
    meshlet_count: u32,
    max_indirect_draws: u32,
    cpu_meshlets: Vec<MeshletGpu>,

    pipeline_cache: vk::PipelineCache,
    desc_set_layout: vk::DescriptorSetLayout,
    pipeline_layout: vk::PipelineLayout,
    desc_pool: vk::DescriptorPool,
    desc_set: vk::DescriptorSet,
    active_psos: ArcSwap<CompiledPsoSet>,
    pso_worker_rx: Option<Receiver<Result<PsoWorkerSuccess, &'static str>>>,
    pso_compile_in_flight: Arc<AtomicBool>,
    retired_psos: Vec<RetiredPsoEntry>,
    async_pso_swaps_completed: u64,

    cmd_pool: vk::CommandPool,
    cmd_buf: vk::CommandBuffer,
    query_pool: vk::QueryPool,
    timeline_sem: vk::Semaphore,
    timeline_counter: u64,

    brick_headers_buf: GpuBufferSlot,
    sdf_cells_buf: GpuBufferSlot,
    meshlets_buf: GpuBufferSlot,
    vertices_buf: GpuBufferSlot,
    indices_buf: GpuBufferSlot,
    skin_dq_buf: GpuBufferSlot,
    vis64_buf: GpuBufferSlot,
    vis_r32_fallback_buf: GpuBufferSlot,
    gbuf_shaded_buf: GpuBufferSlot,
    gbuf_normal_buf: GpuBufferSlot,
    hdr_lit_buf: GpuBufferSlot,
    hiz_mip0_buf: GpuBufferSlot,
    hiz_mip1_buf: GpuBufferSlot,
    indirect_cmds_buf: GpuBufferSlot,
    indirect_count_buf: GpuBufferSlot,
    compacted_indices_buf: GpuBufferSlot,
    scene_bda_buf: GpuBufferSlot,
    readback_buf: GpuBufferSlot,

    cel_lut_img: GpuImageSlot,
    cel_lut_sampler: vk::Sampler,
    out_color_img: GpuImageSlot,
    vis_depth_img: GpuImageSlot,
    fallback_r32_img: Option<GpuImageSlot>,
    presenter: Option<SwapchainPresenter>,

    staged_brick_coords: Vec<BrickCoord>,
    allocator: Mutex<Option<Allocator>>,
}

impl VulkanHybridRenderer {
    /// Creates the Vulkan 1.4 (with automatic 1.3 fallback) Bindless/BDA hybrid renderer.
    pub fn new(
        window_opt: Option<&winit::window::Window>,
        render_width: u32,
        render_height: u32,
        assets: &StreamedAssetBundle,
    ) -> Result<Self, &'static str> {
        Self::new_with_validation(window_opt, render_width, render_height, assets, false)
    }

    /// Creates the Vulkan 1.4/1.3 Bindless/BDA hybrid renderer, optionally attaching
    /// `VK_LAYER_KHRONOS_validation` + `SYNCHRONIZATION_VALIDATION` (`게임.md §8.2, §10.1`).
    pub fn new_with_validation(
        window_opt: Option<&winit::window::Window>,
        render_width: u32,
        render_height: u32,
        assets: &StreamedAssetBundle,
        enable_validation: bool,
    ) -> Result<Self, &'static str> {
        let width = render_width.clamp(64, 1920);
        let height = render_height.clamp(64, 1080);

        // SAFETY: Standard Vulkan 1.4/1.3 initialization, feature negotiation, and resource creation.
        unsafe {
            let entry = ash::Entry::load().map_err(|_| "Failed loading vulkan-1.dll")?;
            let inst_ver = entry
                .try_enumerate_instance_version()
                .map_err(|_| "enumerate_instance_version failed")?
                .unwrap_or(vk::API_VERSION_1_0);
            if vk::api_version_major(inst_ver) < 1 || vk::api_version_minor(inst_ver) < 3 {
                return Err("Vulkan >= 1.3 runtime required");
            }
            let target_minor = if vk::api_version_minor(inst_ver) >= 4 { 4 } else { 3 };
            let req_api = vk::make_api_version(0, 1, target_minor, 0);

            let mut inst_exts: Vec<*const i8> = Vec::new();
            if let Some(win) = window_opt
                && let Ok(dh) = win.display_handle()
                && let Ok(req_exts) = ash_window::enumerate_required_extensions(dh.as_raw())
            {
                inst_exts.extend_from_slice(req_exts);
            }

            let mut inst_layers: Vec<*const i8> = Vec::new();
            if enable_validation {
                let avail_layers = entry
                    .enumerate_instance_layer_properties()
                    .map_err(|_| "enumerate_instance_layer_properties failed")?;
                let has_khronos_val = avail_layers.iter().any(|l| {
                    CStr::from_ptr(l.layer_name.as_ptr()) == c"VK_LAYER_KHRONOS_validation"
                });
                if !has_khronos_val {
                    return Err("VK_LAYER_KHRONOS_validation layer missing (fail-closed §10.1)");
                }
                let avail_inst_exts = entry
                    .enumerate_instance_extension_properties(None)
                    .map_err(|_| "enumerate_instance_extension_properties failed")?;
                let avail_layer_exts = entry
                    .enumerate_instance_extension_properties(Some(c"VK_LAYER_KHRONOS_validation"))
                    .unwrap_or_default();
                let has_dbg_ext = avail_inst_exts
                    .iter()
                    .chain(avail_layer_exts.iter())
                    .any(|e| {
                        CStr::from_ptr(e.extension_name.as_ptr()) == ash::ext::debug_utils::NAME
                    });
                let has_val_feat_ext = avail_inst_exts
                    .iter()
                    .chain(avail_layer_exts.iter())
                    .any(|e| {
                        CStr::from_ptr(e.extension_name.as_ptr())
                            == vk::EXT_VALIDATION_FEATURES_NAME
                    });
                if !has_dbg_ext || !has_val_feat_ext {
                    return Err(
                        "VK_EXT_debug_utils / VK_EXT_validation_features missing (fail-closed §10.1)",
                    );
                }
                inst_layers.push(c"VK_LAYER_KHRONOS_validation".as_ptr());
                inst_exts.push(ash::ext::debug_utils::NAME.as_ptr());
                inst_exts.push(vk::EXT_VALIDATION_FEATURES_NAME.as_ptr());
            }

            let app_info = vk::ApplicationInfo::default()
                .application_name(c"custom_q32_client")
                .engine_name(c"custom_q32_engine")
                .api_version(req_api);
            let sync_enables = [vk::ValidationFeatureEnableEXT::SYNCHRONIZATION_VALIDATION];
            let mut val_features =
                vk::ValidationFeaturesEXT::default().enabled_validation_features(&sync_enables);
            let mut inst_info = vk::InstanceCreateInfo::default()
                .application_info(&app_info)
                .enabled_layer_names(&inst_layers)
                .enabled_extension_names(&inst_exts);
            if enable_validation {
                inst_info = inst_info.push_next(&mut val_features);
            }
            let instance = entry
                .create_instance(&inst_info, None)
                .map_err(|_| "vkCreateInstance failed")?;

            let debug_utils = if enable_validation {
                let dbg_loader = ash::ext::debug_utils::Instance::new(&entry, &instance);
                let dbg_info = vk::DebugUtilsMessengerCreateInfoEXT::default()
                    .message_severity(
                        vk::DebugUtilsMessageSeverityFlagsEXT::ERROR
                            | vk::DebugUtilsMessageSeverityFlagsEXT::WARNING,
                    )
                    .message_type(
                        vk::DebugUtilsMessageTypeFlagsEXT::VALIDATION
                            | vk::DebugUtilsMessageTypeFlagsEXT::PERFORMANCE,
                    )
                    .pfn_user_callback(Some(vk_render_host_debug_callback));
                match dbg_loader.create_debug_utils_messenger(&dbg_info, None) {
                    Ok(m) => Some((dbg_loader, m)),
                    Err(_) => {
                        instance.destroy_instance(None);
                        return Err("vkCreateDebugUtilsMessengerEXT failed (fail-closed §10.1)");
                    }
                }
            } else {
                None
            };

            let mut opt_surface: Option<(ash::khr::surface::Instance, vk::SurfaceKHR)> = None;
            if let Some(win) = window_opt
                && let (Ok(dh), Ok(wh)) = (win.display_handle(), win.window_handle())
                && let Ok(surf) =
                    ash_window::create_surface(&entry, &instance, dh.as_raw(), wh.as_raw(), None)
            {
                let surf_loader = ash::khr::surface::Instance::new(&entry, &instance);
                opt_surface = Some((surf_loader, surf));
            }

            let pdevices = instance
                .enumerate_physical_devices()
                .map_err(|_| "No Vulkan physical devices")?;
            let pdev = *pdevices.first().ok_or("Empty Vulkan physical device list")?;
            let pdev_props = instance.get_physical_device_properties(pdev);
            let dev_minor = vk::api_version_minor(pdev_props.api_version).min(target_minor);
            let timestamp_period_ns = f64::from(pdev_props.limits.timestamp_period);

            let qfamilies = instance.get_physical_device_queue_family_properties(pdev);
            let qf_idx = qfamilies
                .iter()
                .enumerate()
                .find(|(_, qf)| {
                    qf.queue_flags
                        .contains(vk::QueueFlags::GRAPHICS | vk::QueueFlags::COMPUTE)
                        && qf.timestamp_valid_bits > 0
                })
                .map(|(i, _)| i as u32)
                .ok_or("No graphics+compute queue family with timestamp support")?;

            let dev_exts_avail = instance
                .enumerate_device_extension_properties(pdev)
                .unwrap_or_default();
            let has_ext = |ext_name: &CStr| -> bool {
                dev_exts_avail
                    .iter()
                    .any(|e| CStr::from_ptr(e.extension_name.as_ptr()) == ext_name)
            };

            // Query hardware features (`Vulkan 1.1 / 1.2 / 1.3` + `Vulkan 1.4` promoted extensions):
            let mut q_v11 = vk::PhysicalDeviceVulkan11Features::default();
            let mut q_v12 = vk::PhysicalDeviceVulkan12Features::default();
            let mut q_v13 = vk::PhysicalDeviceVulkan13Features::default();
            let mut q_hic = vk::PhysicalDeviceHostImageCopyFeaturesEXT::default();
            let mut q_drlr = vk::PhysicalDeviceDynamicRenderingLocalReadFeaturesKHR::default();
            let mut q_m5 = vk::PhysicalDeviceMaintenance5FeaturesKHR::default();
            let mut q_pid = vk::PhysicalDevicePresentIdFeaturesKHR::default();
            let mut q_pwait = vk::PhysicalDevicePresentWaitFeaturesKHR::default();
            let mut q_rq = vk::PhysicalDeviceRayQueryFeaturesKHR::default();
            let mut q_ms = vk::PhysicalDeviceMeshShaderFeaturesEXT::default();

            let raw_core_feats = {
                let mut q_feat2 = vk::PhysicalDeviceFeatures2::default()
                    .push_next(&mut q_v11)
                    .push_next(&mut q_v12)
                    .push_next(&mut q_v13)
                    .push_next(&mut q_hic)
                    .push_next(&mut q_drlr)
                    .push_next(&mut q_m5)
                    .push_next(&mut q_pid)
                    .push_next(&mut q_pwait)
                    .push_next(&mut q_rq)
                    .push_next(&mut q_ms);
                instance.get_physical_device_features2(pdev, &mut q_feat2);
                q_feat2.features
            };

            if q_v13.synchronization2 == vk::FALSE
                || q_v13.dynamic_rendering == vk::FALSE
                || q_v12.timeline_semaphore == vk::FALSE
            {
                return Err("GPU missing mandatory Vulkan 1.3 synchronization2/dynamicRendering/timelineSemaphore");
            }

            let mut fmt_props3 = vk::FormatProperties3::default();
            let mut fmt_props2 = vk::FormatProperties2::default().push_next(&mut fmt_props3);
            instance.get_physical_device_format_properties2(
                pdev,
                vk::Format::R8G8B8A8_UNORM,
                &mut fmt_props2,
            );
            let fmt_has_host_xfer = fmt_props3
                .optimal_tiling_features
                .contains(vk::FormatFeatureFlags2::HOST_IMAGE_TRANSFER_EXT);

            let has_int64 = raw_core_feats.shader_int64 == vk::TRUE;
            let has_frag_stores = raw_core_feats.fragment_stores_and_atomics == vk::TRUE;
            let has_sampled_dyn =
                raw_core_feats.shader_sampled_image_array_dynamic_indexing == vk::TRUE;
            let has_int64_atomics =
                has_int64 && has_frag_stores && (q_v12.shader_buffer_int64_atomics == vk::TRUE);
            let has_bda = q_v12.buffer_device_address == vk::TRUE;
            let has_draw_params = q_v11.shader_draw_parameters == vk::TRUE;
            let has_indirect_count = q_v12.draw_indirect_count == vk::TRUE;
            let has_sampled_non_uniform = has_sampled_dyn
                && (q_v12.shader_sampled_image_array_non_uniform_indexing == vk::TRUE);

            let has_swapchain_ext = has_ext(ash::khr::swapchain::NAME);
            let can_enable_hic = has_ext(ash::ext::host_image_copy::NAME)
                && (q_hic.host_image_copy == vk::TRUE)
                && fmt_has_host_xfer;
            let can_enable_drlr = has_ext(ash::khr::dynamic_rendering_local_read::NAME)
                && (q_drlr.dynamic_rendering_local_read == vk::TRUE);
            let can_enable_m5 =
                has_ext(ash::khr::maintenance5::NAME) && (q_m5.maintenance5 == vk::TRUE);
            let can_enable_pwait = opt_surface.is_some()
                && has_swapchain_ext
                && has_ext(ash::khr::present_id::NAME)
                && has_ext(ash::khr::present_wait::NAME)
                && (q_pid.present_id == vk::TRUE)
                && (q_pwait.present_wait == vk::TRUE);
            let has_gpl = has_ext(ash::ext::graphics_pipeline_library::NAME)
                && has_ext(ash::khr::pipeline_library::NAME);
            let has_rq = has_ext(ash::khr::acceleration_structure::NAME)
                && has_ext(ash::khr::ray_query::NAME)
                && (q_rq.ray_query == vk::TRUE);
            let has_ms =
                has_ext(ash::ext::mesh_shader::NAME) && (q_ms.mesh_shader == vk::TRUE);

            let caps = HardwareVulkanCaps {
                vulkan_minor: dev_minor,
                shader_int64: has_int64,
                shader_int64_atomics: has_int64_atomics,
                buffer_device_address: has_bda,
                host_image_copy: can_enable_hic,
                draw_parameters: has_draw_params,
                draw_indirect_count: has_indirect_count,
                fragment_stores_and_atomics: has_frag_stores,
                sampled_image_non_uniform: has_sampled_non_uniform,
                dynamic_rendering_local_read: can_enable_drlr,
                maintenance5: can_enable_m5,
                graphics_pipeline_library: has_gpl,
                present_wait: can_enable_pwait,
                ray_query: has_rq,
                mesh_shader: has_ms,
            };

            let mut enabled_dev_exts: Vec<*const i8> = Vec::new();
            if opt_surface.is_some() && has_swapchain_ext {
                enabled_dev_exts.push(ash::khr::swapchain::NAME.as_ptr());
            }
            if can_enable_hic {
                enabled_dev_exts.push(ash::ext::host_image_copy::NAME.as_ptr());
            }
            if can_enable_drlr {
                enabled_dev_exts.push(ash::khr::dynamic_rendering_local_read::NAME.as_ptr());
            }
            if can_enable_m5 {
                enabled_dev_exts.push(ash::khr::maintenance5::NAME.as_ptr());
            }
            if can_enable_pwait {
                enabled_dev_exts.push(ash::khr::present_id::NAME.as_ptr());
                enabled_dev_exts.push(ash::khr::present_wait::NAME.as_ptr());
            }

            let priorities = [1.0_f32];
            let q_info = vk::DeviceQueueCreateInfo::default()
                .queue_family_index(qf_idx)
                .queue_priorities(&priorities);

            let has_uab_ssbo = q_v12.descriptor_indexing == vk::TRUE
                && q_v12.descriptor_binding_storage_buffer_update_after_bind == vk::TRUE
                && q_v12.descriptor_binding_partially_bound == vk::TRUE;
            let has_uab_sampled =
                q_v12.descriptor_binding_sampled_image_update_after_bind == vk::TRUE;
            let has_uab_img = q_v12.descriptor_binding_storage_image_update_after_bind == vk::TRUE;

            let base_feats = vk::PhysicalDeviceFeatures::default()
                .shader_int64(has_int64)
                .fragment_stores_and_atomics(has_frag_stores)
                .shader_sampled_image_array_dynamic_indexing(has_sampled_dyn);
            let mut en_v11 = vk::PhysicalDeviceVulkan11Features::default()
                .shader_draw_parameters(has_draw_params);
            let mut en_v12 = vk::PhysicalDeviceVulkan12Features::default()
                .timeline_semaphore(true)
                .buffer_device_address(has_bda)
                .shader_buffer_int64_atomics(has_int64_atomics)
                .draw_indirect_count(has_indirect_count)
                .descriptor_indexing(q_v12.descriptor_indexing == vk::TRUE)
                .shader_sampled_image_array_non_uniform_indexing(has_sampled_non_uniform)
                .descriptor_binding_sampled_image_update_after_bind(has_uab_sampled)
                .descriptor_binding_storage_buffer_update_after_bind(
                    q_v12.descriptor_binding_storage_buffer_update_after_bind == vk::TRUE,
                )
                .descriptor_binding_storage_image_update_after_bind(has_uab_img)
                .descriptor_binding_partially_bound(
                    q_v12.descriptor_binding_partially_bound == vk::TRUE,
                );
            let mut en_v13 = vk::PhysicalDeviceVulkan13Features::default()
                .synchronization2(true)
                .dynamic_rendering(true);
            let mut en_hic =
                vk::PhysicalDeviceHostImageCopyFeaturesEXT::default().host_image_copy(true);
            let mut en_drlr = vk::PhysicalDeviceDynamicRenderingLocalReadFeaturesKHR::default()
                .dynamic_rendering_local_read(true);
            let mut en_m5 =
                vk::PhysicalDeviceMaintenance5FeaturesKHR::default().maintenance5(true);
            let mut en_pid = vk::PhysicalDevicePresentIdFeaturesKHR::default().present_id(true);
            let mut en_pwait =
                vk::PhysicalDevicePresentWaitFeaturesKHR::default().present_wait(true);

            let mut dev_info = vk::DeviceCreateInfo::default()
                .queue_create_infos(core::slice::from_ref(&q_info))
                .enabled_extension_names(&enabled_dev_exts)
                .enabled_features(&base_feats)
                .push_next(&mut en_v11)
                .push_next(&mut en_v12)
                .push_next(&mut en_v13);
            if can_enable_hic {
                dev_info = dev_info.push_next(&mut en_hic);
            }
            if can_enable_drlr {
                dev_info = dev_info.push_next(&mut en_drlr);
            }
            if can_enable_m5 {
                dev_info = dev_info.push_next(&mut en_m5);
            }
            if can_enable_pwait {
                dev_info = dev_info.push_next(&mut en_pid).push_next(&mut en_pwait);
            }

            let device = instance
                .create_device(pdev, &dev_info, None)
                .map_err(|_| "vkCreateDevice failed")?;
            let queue = device.get_device_queue(qf_idx, 0);

            let mut alloc = Allocator::new(&AllocatorCreateDesc {
                instance: instance.clone(),
                device: device.clone(),
                physical_device: pdev,
                debug_settings: Default::default(),
                buffer_device_address: has_bda,
                allocation_sizes: Default::default(),
            })
            .map_err(|_| "gpu_allocator::Allocator::new failed")?;

            // Create Set 0 Unified Bindless Descriptor Layout (`0..=18`, Binding 11 = 16-slot `COMBINED_IMAGE_SAMPLER`!):
            let all_stages = vk::ShaderStageFlags::COMPUTE
                | vk::ShaderStageFlags::VERTEX
                | vk::ShaderStageFlags::FRAGMENT;
            let mut bindings = Vec::with_capacity(19);
            let mut binding_flags = Vec::with_capacity(19);
            let mut bi: u32 = 0;
            while bi <= 18 {
                if bi == 11 {
                    bindings.push(
                        vk::DescriptorSetLayoutBinding::default()
                            .binding(11)
                            .descriptor_type(vk::DescriptorType::COMBINED_IMAGE_SAMPLER)
                            .descriptor_count(BINDLESS_TEXTURE_SLOTS)
                            .stage_flags(all_stages),
                    );
                    binding_flags.push(if has_uab_ssbo && has_uab_sampled {
                        vk::DescriptorBindingFlags::UPDATE_AFTER_BIND
                            | vk::DescriptorBindingFlags::PARTIALLY_BOUND
                    } else if has_uab_ssbo {
                        vk::DescriptorBindingFlags::PARTIALLY_BOUND
                    } else {
                        vk::DescriptorBindingFlags::empty()
                    });
                } else if bi == 12 {
                    bindings.push(
                        vk::DescriptorSetLayoutBinding::default()
                            .binding(12)
                            .descriptor_type(vk::DescriptorType::STORAGE_IMAGE)
                            .descriptor_count(1)
                            .stage_flags(vk::ShaderStageFlags::COMPUTE),
                    );
                    binding_flags.push(if has_uab_ssbo && has_uab_img {
                        vk::DescriptorBindingFlags::UPDATE_AFTER_BIND
                            | vk::DescriptorBindingFlags::PARTIALLY_BOUND
                    } else if has_uab_ssbo {
                        vk::DescriptorBindingFlags::PARTIALLY_BOUND
                    } else {
                        vk::DescriptorBindingFlags::empty()
                    });
                } else {
                    bindings.push(
                        vk::DescriptorSetLayoutBinding::default()
                            .binding(bi)
                            .descriptor_type(vk::DescriptorType::STORAGE_BUFFER)
                            .descriptor_count(1)
                            .stage_flags(all_stages),
                    );
                    binding_flags.push(if has_uab_ssbo {
                        vk::DescriptorBindingFlags::UPDATE_AFTER_BIND
                            | vk::DescriptorBindingFlags::PARTIALLY_BOUND
                    } else {
                        vk::DescriptorBindingFlags::empty()
                    });
                }
                bi = bi.saturating_add(1);
            }

            let mut dsl_flags_info =
                vk::DescriptorSetLayoutBindingFlagsCreateInfo::default().binding_flags(&binding_flags);
            let dsl_info = vk::DescriptorSetLayoutCreateInfo::default()
                .flags(if has_uab_ssbo {
                    vk::DescriptorSetLayoutCreateFlags::UPDATE_AFTER_BIND_POOL
                } else {
                    vk::DescriptorSetLayoutCreateFlags::empty()
                })
                .bindings(&bindings)
                .push_next(&mut dsl_flags_info);
            let desc_set_layout = device
                .create_descriptor_set_layout(&dsl_info, None)
                .map_err(|_| "create_descriptor_set_layout failed")?;

            let push_range = vk::PushConstantRange {
                stage_flags: all_stages,
                offset: 0,
                size: core::mem::size_of::<FramePushConstants>() as u32,
            };
            let pl_info = vk::PipelineLayoutCreateInfo::default()
                .set_layouts(core::slice::from_ref(&desc_set_layout))
                .push_constant_ranges(core::slice::from_ref(&push_range));
            let pipeline_layout = device
                .create_pipeline_layout(&pl_info, None)
                .map_err(|_| "create_pipeline_layout failed")?;

            let pc_info = vk::PipelineCacheCreateInfo::default();
            let pipeline_cache = device
                .create_pipeline_cache(&pc_info, None)
                .map_err(|_| "create_pipeline_cache failed")?;

            let pso_set = Self::compile_pso_bundle(&device, pipeline_layout, pipeline_cache, &caps)?;
            let active_psos = ArcSwap::from_pointee(pso_set);

            // Command Pool, Command Buffer, Timestamp QueryPool & Timeline Semaphore (`게임.md §8.2`):
            let cp_info = vk::CommandPoolCreateInfo::default()
                .queue_family_index(qf_idx)
                .flags(vk::CommandPoolCreateFlags::RESET_COMMAND_BUFFER);
            let cmd_pool = device
                .create_command_pool(&cp_info, None)
                .map_err(|_| "create_command_pool failed")?;
            let cb_info = vk::CommandBufferAllocateInfo::default()
                .command_pool(cmd_pool)
                .level(vk::CommandBufferLevel::PRIMARY)
                .command_buffer_count(1);
            let cmd_buf = *device
                .allocate_command_buffers(&cb_info)
                .map_err(|_| "allocate_command_buffers failed")?
                .first()
                .ok_or("Missing command buffer")?;

            let qp_info = vk::QueryPoolCreateInfo::default()
                .query_type(vk::QueryType::TIMESTAMP)
                .query_count(4);
            let query_pool = device
                .create_query_pool(&qp_info, None)
                .map_err(|_| "create_query_pool failed")?;

            let mut sem_type = vk::SemaphoreTypeCreateInfo::default()
                .semaphore_type(vk::SemaphoreType::TIMELINE)
                .initial_value(0);
            let sem_info = vk::SemaphoreCreateInfo::default().push_next(&mut sem_type);
            let timeline_sem = device
                .create_semaphore(&sem_info, None)
                .map_err(|_| "create_semaphore(TIMELINE) failed")?;
            let mut timeline_counter: u64 = 0;

            // Allocate GPU Buffers via `gpu-allocator`:
            let pixel_count = (width as usize).saturating_mul(height as usize).max(1);
            let tile_count = ((width.saturating_add(7) >> 3) as usize)
                .saturating_mul((height.saturating_add(7) >> 3) as usize)
                .max(1);
            let std_ssbo = vk::BufferUsageFlags::STORAGE_BUFFER
                | vk::BufferUsageFlags::TRANSFER_DST
                | vk::BufferUsageFlags::TRANSFER_SRC;

            let brick_headers_buf = Self::alloc_buffer_ext(
                &device,
                &mut alloc,
                "brick_headers_ssbo",
                MAX_GPU_BRICKS.saturating_mul(core::mem::size_of::<BrickHeaderGpu>()) as u64,
                MemoryLocation::CpuToGpu,
                std_ssbo,
                has_bda,
            )?;
            let sdf_cells_buf = Self::alloc_buffer_ext(
                &device,
                &mut alloc,
                "sdf_cells_ssbo",
                MAX_GPU_BRICKS
                    .saturating_mul(BRICK_CELL_COUNT)
                    .saturating_mul(core::mem::size_of::<i32>()) as u64,
                MemoryLocation::CpuToGpu,
                std_ssbo,
                has_bda,
            )?;
            let meshlets_buf = Self::alloc_buffer_ext(
                &device,
                &mut alloc,
                "meshlets_ssbo",
                assets
                    .meshlets
                    .len()
                    .max(1)
                    .saturating_mul(core::mem::size_of::<MeshletGpu>()) as u64,
                MemoryLocation::CpuToGpu,
                std_ssbo,
                has_bda,
            )?;
            let vertices_buf = Self::alloc_buffer_ext(
                &device,
                &mut alloc,
                "vertices_ssbo",
                assets
                    .vertices
                    .len()
                    .max(1)
                    .saturating_mul(core::mem::size_of::<[f32; 4]>()) as u64,
                MemoryLocation::CpuToGpu,
                std_ssbo,
                has_bda,
            )?;
            let indices_buf = Self::alloc_buffer_ext(
                &device,
                &mut alloc,
                "indices_ssbo",
                assets
                    .indices
                    .len()
                    .max(1)
                    .saturating_mul(core::mem::size_of::<u32>()) as u64,
                MemoryLocation::CpuToGpu,
                std_ssbo,
                has_bda,
            )?;
            let skin_dq_buf = Self::alloc_buffer_ext(
                &device,
                &mut alloc,
                "skin_dq_ssbo",
                BONE_PALETTE_CAP.saturating_mul(core::mem::size_of::<DualQuatGpu>()) as u64,
                MemoryLocation::CpuToGpu,
                std_ssbo,
                has_bda,
            )?;
            let vis64_buf = Self::alloc_buffer_ext(
                &device,
                &mut alloc,
                "vis_buffer_64_ssbo",
                pixel_count.saturating_mul(core::mem::size_of::<u64>()) as u64,
                MemoryLocation::GpuOnly,
                std_ssbo,
                has_bda,
            )?;
            let vis_r32_fallback_buf = Self::alloc_buffer_ext(
                &device,
                &mut alloc,
                "vis_fallback_r32_ssbo",
                pixel_count.saturating_mul(core::mem::size_of::<u32>()) as u64,
                MemoryLocation::GpuOnly,
                std_ssbo,
                has_bda,
            )?;
            let gbuf_shaded_buf = Self::alloc_buffer_ext(
                &device,
                &mut alloc,
                "gbuf_shaded_ssbo",
                pixel_count.saturating_mul(core::mem::size_of::<[f32; 4]>()) as u64,
                MemoryLocation::GpuOnly,
                std_ssbo,
                has_bda,
            )?;
            let gbuf_normal_buf = Self::alloc_buffer_ext(
                &device,
                &mut alloc,
                "gbuf_normal_ssbo",
                pixel_count.saturating_mul(core::mem::size_of::<[f32; 4]>()) as u64,
                MemoryLocation::GpuOnly,
                std_ssbo,
                has_bda,
            )?;
            let hdr_lit_buf = Self::alloc_buffer_ext(
                &device,
                &mut alloc,
                "hdr_lit_ssbo",
                pixel_count.saturating_mul(core::mem::size_of::<[f32; 4]>()) as u64,
                MemoryLocation::GpuOnly,
                std_ssbo,
                has_bda,
            )?;
            let hiz_mip0_buf = Self::alloc_buffer_ext(
                &device,
                &mut alloc,
                "hiz_mip0_ssbo",
                pixel_count.saturating_mul(core::mem::size_of::<u32>()) as u64,
                MemoryLocation::GpuOnly,
                std_ssbo,
                has_bda,
            )?;
            let hiz_mip1_buf = Self::alloc_buffer_ext(
                &device,
                &mut alloc,
                "hiz_mip1_ssbo",
                tile_count.saturating_mul(core::mem::size_of::<u32>()) as u64,
                MemoryLocation::GpuOnly,
                std_ssbo,
                has_bda,
            )?;
            let indirect_cmds_buf = Self::alloc_buffer_ext(
                &device,
                &mut alloc,
                "indirect_cmds_ssbo",
                MAX_INDIRECT_CLUSTERS
                    .saturating_mul(core::mem::size_of::<DrawIndexedIndirectCmdGpu>()) as u64,
                MemoryLocation::GpuOnly,
                std_ssbo | vk::BufferUsageFlags::INDIRECT_BUFFER,
                has_bda,
            )?;
            let indirect_count_buf = Self::alloc_buffer_ext(
                &device,
                &mut alloc,
                "indirect_count_ssbo",
                64,
                MemoryLocation::GpuOnly,
                std_ssbo | vk::BufferUsageFlags::INDIRECT_BUFFER,
                has_bda,
            )?;
            let compacted_indices_buf = Self::alloc_buffer_ext(
                &device,
                &mut alloc,
                "compacted_indices_ssbo",
                MAX_INDIRECT_CLUSTERS.saturating_mul(3).saturating_mul(core::mem::size_of::<u32>()) as u64,
                MemoryLocation::GpuOnly,
                std_ssbo | vk::BufferUsageFlags::INDEX_BUFFER,
                has_bda,
            )?;
            let scene_bda_buf = Self::alloc_buffer_ext(
                &device,
                &mut alloc,
                "scene_bda_header_buf",
                core::mem::size_of::<GpuSceneBdaHeader>() as u64,
                MemoryLocation::CpuToGpu,
                std_ssbo,
                has_bda,
            )?;
            let readback_buf = Self::alloc_buffer_ext(
                &device,
                &mut alloc,
                "offscreen_readback_buf",
                pixel_count.saturating_mul(4) as u64,
                MemoryLocation::GpuToCpu,
                vk::BufferUsageFlags::TRANSFER_DST,
                false,
            )?;

            // Upload static meshlets, vertices, and indices immediately:
            Self::write_pod_slice(&meshlets_buf, &assets.meshlets)?;
            Self::write_pod_slice(&vertices_buf, &assets.vertices)?;
            Self::write_pod_slice(&indices_buf, &assets.indices)?;

            // Create & upload mipmapped `KTX2` Cel-LUT `VkImage` (`VK_EXT_host_image_copy` or Vulkan 1.3 staging fallback):
            let mip_count = assets.cel_lut_mips.len().max(1) as u32;
            let lut_w = assets.cel_lut_mips.first().map(|m| m.width).unwrap_or(16);
            let lut_h = assets.cel_lut_mips.first().map(|m| m.height).unwrap_or(4);
            let mut lut_usage =
                vk::ImageUsageFlags::SAMPLED | vk::ImageUsageFlags::TRANSFER_DST;
            if caps.host_image_copy {
                lut_usage |= vk::ImageUsageFlags::HOST_TRANSFER_EXT;
            }
            let cel_lut_img = Self::alloc_image_mips(
                &device,
                &mut alloc,
                "ktx2_cel_lut_mips",
                (
                    vk::Extent2D {
                        width: lut_w,
                        height: lut_h,
                    },
                    mip_count,
                ),
                vk::Format::R8G8B8A8_UNORM,
                lut_usage,
                vk::ImageAspectFlags::COLOR,
            )?;
            let used_hic_upload = Self::upload_ktx2_mips(
                (&instance, &device),
                &mut alloc,
                (queue, cmd_buf, timeline_sem, &mut timeline_counter),
                cel_lut_img.image,
                &assets.cel_lut_mips,
                caps.host_image_copy,
            )?;
            let sampler_info = vk::SamplerCreateInfo::default()
                .mag_filter(vk::Filter::LINEAR)
                .min_filter(vk::Filter::LINEAR)
                .mipmap_mode(vk::SamplerMipmapMode::LINEAR)
                .address_mode_u(vk::SamplerAddressMode::CLAMP_TO_EDGE)
                .address_mode_v(vk::SamplerAddressMode::CLAMP_TO_EDGE)
                .address_mode_w(vk::SamplerAddressMode::CLAMP_TO_EDGE)
                .min_lod(0.0)
                .max_lod(mip_count as f32);
            let cel_lut_sampler = device
                .create_sampler(&sampler_info, None)
                .map_err(|_| "create_sampler failed")?;

            let target_extent = vk::Extent2D { width, height };
            let out_color_img = Self::alloc_image_mips(
                &device,
                &mut alloc,
                "out_color_rgba8",
                (target_extent, 1),
                vk::Format::R8G8B8A8_UNORM,
                vk::ImageUsageFlags::STORAGE
                    | vk::ImageUsageFlags::COLOR_ATTACHMENT
                    | vk::ImageUsageFlags::TRANSFER_SRC
                    | vk::ImageUsageFlags::TRANSFER_DST,
                vk::ImageAspectFlags::COLOR,
            )?;
            let vis_depth_img = Self::alloc_image_mips(
                &device,
                &mut alloc,
                "vis_earlyz_depth_d32",
                (target_extent, 1),
                vk::Format::D32_SFLOAT,
                vk::ImageUsageFlags::DEPTH_STENCIL_ATTACHMENT,
                vk::ImageAspectFlags::DEPTH,
            )?;
            let fallback_r32_img = if !caps.shader_int64_atomics || !caps.buffer_device_address {
                Some(Self::alloc_image_mips(
                    &device,
                    &mut alloc,
                    "fallback_vis_r32",
                    (target_extent, 1),
                    vk::Format::R32_UINT,
                    vk::ImageUsageFlags::COLOR_ATTACHMENT | vk::ImageUsageFlags::TRANSFER_SRC,
                    vk::ImageAspectFlags::COLOR,
                )?)
            } else {
                None
            };

            // Descriptor Pool & Set Binding (`0..=18`, Binding 11 = 16-slot Global Bindless Sampler Array):
            let pool_sizes = [
                vk::DescriptorPoolSize {
                    ty: vk::DescriptorType::STORAGE_BUFFER,
                    descriptor_count: 17,
                },
                vk::DescriptorPoolSize {
                    ty: vk::DescriptorType::COMBINED_IMAGE_SAMPLER,
                    descriptor_count: BINDLESS_TEXTURE_SLOTS,
                },
                vk::DescriptorPoolSize {
                    ty: vk::DescriptorType::STORAGE_IMAGE,
                    descriptor_count: 1,
                },
            ];
            let dp_info = vk::DescriptorPoolCreateInfo::default()
                .flags(if has_uab_ssbo {
                    vk::DescriptorPoolCreateFlags::UPDATE_AFTER_BIND
                } else {
                    vk::DescriptorPoolCreateFlags::empty()
                })
                .max_sets(1)
                .pool_sizes(&pool_sizes);
            let desc_pool = device
                .create_descriptor_pool(&dp_info, None)
                .map_err(|_| "create_descriptor_pool failed")?;
            let ds_alloc = vk::DescriptorSetAllocateInfo::default()
                .descriptor_pool(desc_pool)
                .set_layouts(core::slice::from_ref(&desc_set_layout));
            let desc_set = *device
                .allocate_descriptor_sets(&ds_alloc)
                .map_err(|_| "allocate_descriptor_sets failed")?
                .first()
                .ok_or("Missing descriptor set")?;

            let ssbo_bindings: [(u32, vk::Buffer); 17] = [
                (0, brick_headers_buf.buffer),
                (1, sdf_cells_buf.buffer),
                (2, meshlets_buf.buffer),
                (3, vertices_buf.buffer),
                (4, indices_buf.buffer),
                (5, skin_dq_buf.buffer),
                (6, vis64_buf.buffer),
                (7, vis_r32_fallback_buf.buffer),
                (8, gbuf_shaded_buf.buffer),
                (9, gbuf_normal_buf.buffer),
                (10, hdr_lit_buf.buffer),
                (13, hiz_mip0_buf.buffer),
                (14, hiz_mip1_buf.buffer),
                (15, indirect_cmds_buf.buffer),
                (16, indirect_count_buf.buffer),
                (17, compacted_indices_buf.buffer),
                (18, scene_bda_buf.buffer),
            ];
            let buf_infos: Vec<vk::DescriptorBufferInfo> = ssbo_bindings
                .iter()
                .map(|(_, b)| vk::DescriptorBufferInfo {
                    buffer: *b,
                    offset: 0,
                    range: vk::WHOLE_SIZE,
                })
                .collect();

            let lut_img_info = vk::DescriptorImageInfo {
                sampler: cel_lut_sampler,
                image_view: cel_lut_img.view,
                image_layout: vk::ImageLayout::SHADER_READ_ONLY_OPTIMAL,
            };
            let bindless_lut_infos = [lut_img_info; BINDLESS_TEXTURE_SLOTS as usize];

            let out_img_info = vk::DescriptorImageInfo {
                sampler: vk::Sampler::null(),
                image_view: out_color_img.view,
                image_layout: vk::ImageLayout::GENERAL,
            };

            let mut writes = Vec::with_capacity(19);
            for (i, (binding_idx, _)) in ssbo_bindings.iter().enumerate() {
                writes.push(
                    vk::WriteDescriptorSet::default()
                        .dst_set(desc_set)
                        .dst_binding(*binding_idx)
                        .descriptor_type(vk::DescriptorType::STORAGE_BUFFER)
                        .buffer_info(core::slice::from_ref(&buf_infos[i])),
                );
            }
            writes.push(
                vk::WriteDescriptorSet::default()
                    .dst_set(desc_set)
                    .dst_binding(11)
                    .descriptor_type(vk::DescriptorType::COMBINED_IMAGE_SAMPLER)
                    .image_info(&bindless_lut_infos),
            );
            writes.push(
                vk::WriteDescriptorSet::default()
                    .dst_set(desc_set)
                    .dst_binding(12)
                    .descriptor_type(vk::DescriptorType::STORAGE_IMAGE)
                    .image_info(core::slice::from_ref(&out_img_info)),
            );
            device.update_descriptor_sets(&writes, &[]);

            // Optional `VK_KHR_swapchain` (+ `VK_KHR_present_wait`) presenter setup when window surface is provided:
            let presenter = if let Some((surf_loader, surf)) = opt_surface {
                if has_swapchain_ext {
                    Self::try_init_swapchain(
                        &instance,
                        &device,
                        (pdev, qf_idx),
                        surf_loader,
                        surf,
                        target_extent,
                        can_enable_pwait,
                    )
                } else {
                    surf_loader.destroy_surface(surf, None);
                    None
                }
            } else {
                None
            };

            Ok(Self {
                _entry: entry,
                instance,
                debug_utils,
                device,
                queue,
                caps,
                used_hic_upload,
                timestamp_period_ns,
                width,
                height,
                rest_joint_offsets: assets.rest_joint_offsets,
                meshlet_count: assets.meshlets.len() as u32,
                max_indirect_draws: (assets.indices.len() / 3).clamp(1, MAX_INDIRECT_CLUSTERS)
                    as u32,
                cpu_meshlets: assets.meshlets.clone(),
                pipeline_cache,
                desc_set_layout,
                pipeline_layout,
                desc_pool,
                desc_set,
                active_psos,
                pso_worker_rx: None,
                pso_compile_in_flight: Arc::new(AtomicBool::new(false)),
                retired_psos: Vec::new(),
                async_pso_swaps_completed: 0,
                cmd_pool,
                cmd_buf,
                query_pool,
                timeline_sem,
                timeline_counter,
                brick_headers_buf,
                sdf_cells_buf,
                meshlets_buf,
                vertices_buf,
                indices_buf,
                skin_dq_buf,
                vis64_buf,
                vis_r32_fallback_buf,
                gbuf_shaded_buf,
                gbuf_normal_buf,
                hdr_lit_buf,
                hiz_mip0_buf,
                hiz_mip1_buf,
                indirect_cmds_buf,
                indirect_count_buf,
                compacted_indices_buf,
                scene_bda_buf,
                readback_buf,
                cel_lut_img,
                cel_lut_sampler,
                out_color_img,
                vis_depth_img,
                fallback_r32_img,
                presenter,
                staged_brick_coords: Vec::with_capacity(MAX_GPU_BRICKS),
                allocator: Mutex::new(Some(alloc)),
            })
        }
    }

    #[inline]
    pub const fn hardware_caps(&self) -> HardwareVulkanCaps {
        self.caps
    }

    #[inline]
    pub const fn used_host_image_copy(&self) -> bool {
        self.used_hic_upload
    }

    #[inline]
    pub const fn async_pso_swaps_completed(&self) -> u64 {
        self.async_pso_swaps_completed
    }

    /// Spawns a background OS worker thread compiling a fresh `CompiledPsoSet` against an isolated
    /// `VkPipelineCache` (`0ms` main/render-thread stall, `게임.md §5.2, §8.2`).
    pub fn request_async_pso_hotswap(&mut self) -> Result<bool, &'static str> {
        if self.pso_compile_in_flight.load(Ordering::Acquire) {
            return Ok(false);
        }
        // SAFETY: `get_pipeline_cache_data` reads current driver cache bytes to warm the worker's isolated cache.
        let seed_bytes = unsafe {
            self.device
                .get_pipeline_cache_data(self.pipeline_cache)
                .unwrap_or_default()
        };
        let dev_clone = self.device.clone();
        let layout = self.pipeline_layout;
        let caps = self.caps;
        let in_flight = Arc::clone(&self.pso_compile_in_flight);
        in_flight.store(true, Ordering::Release);
        let (tx, rx) = mpsc::channel();
        self.pso_worker_rx = Some(rx);

        thread::spawn(move || {
            // SAFETY: `dev_clone` and `layout` remain alive (`Drop` joins `pso_worker_rx` before `destroy_device`);
            // `worker_cache` is owned exclusively by this worker thread.
            let res = unsafe {
                let pc_info = vk::PipelineCacheCreateInfo::default().initial_data(&seed_bytes);
                match dev_clone.create_pipeline_cache(&pc_info, None) {
                    Ok(worker_cache) => {
                        match Self::compile_pso_bundle(&dev_clone, layout, worker_cache, &caps) {
                            Ok(pso_set) => Ok(PsoWorkerSuccess {
                                pso_set,
                                worker_cache,
                            }),
                            Err(e) => {
                                dev_clone.destroy_pipeline_cache(worker_cache, None);
                                Err(e)
                            }
                        }
                    }
                    Err(_) => Err("Worker vkCreatePipelineCache failed"),
                }
            };
            in_flight.store(false, Ordering::Release);
            let _ = tx.send(res);
        });
        Ok(true)
    }

    /// Non-blocking poll (`try_recv`) applying any finished background PSO bundle via lock-free `ArcSwap`,
    /// merging `VkPipelineCache`, and retiring previous PSOs strictly after `Timeline Semaphore` completion.
    pub fn poll_async_pso_hotswap(&mut self) -> Result<bool, &'static str> {
        // 1. Reclaim retired PSO bundles whose last frame `Timeline Semaphore` value has completed on GPU:
        // SAFETY: Queries valid timeline semaphore counter on `self.device`.
        let gpu_done = unsafe {
            self.device
                .get_semaphore_counter_value(self.timeline_sem)
                .unwrap_or(0)
        };
        self.retired_psos
            .retain(|entry| entry.retire_after_timeline > gpu_done);

        let Some(rx) = self.pso_worker_rx.as_ref() else {
            return Ok(false);
        };
        match rx.try_recv() {
            Ok(worker_res) => {
                self.pso_worker_rx = None;
                let ok_bundle = worker_res?;
                // SAFETY: Merges and destroys the finished worker-owned `VkPipelineCache` on the main thread.
                unsafe {
                    let _ = self.device.merge_pipeline_caches(
                        self.pipeline_cache,
                        core::slice::from_ref(&ok_bundle.worker_cache),
                    );
                    self.device
                        .destroy_pipeline_cache(ok_bundle.worker_cache, None);
                }
                let prev_arc = self.active_psos.swap(Arc::new(ok_bundle.pso_set));
                self.retired_psos.push(RetiredPsoEntry {
                    retire_after_timeline: self.timeline_counter,
                    _pso_set: prev_arc,
                });
                self.async_pso_swaps_completed = self.async_pso_swaps_completed.saturating_add(1);
                Ok(true)
            }
            Err(TryRecvError::Empty) => Ok(false),
            Err(TryRecvError::Disconnected) => {
                self.pso_worker_rx = None;
                Err("Background PSO compiler worker disconnected")
            }
        }
    }

    /// Synchronous convenience wrapper around background worker PSO compilation + timeline-safe retirement (`#[cfg(test)]` & bootstrap).
    pub fn hot_swap_pipelines_zero_hitch(&mut self) -> Result<(), &'static str> {
        let _ = self.request_async_pso_hotswap()?;
        if let Some(rx) = self.pso_worker_rx.take() {
            let ok_bundle = rx
                .recv()
                .map_err(|_| "PSO worker channel closed")??;
            // SAFETY: Merges and destroys finished worker `VkPipelineCache`.
            unsafe {
                let _ = self.device.merge_pipeline_caches(
                    self.pipeline_cache,
                    core::slice::from_ref(&ok_bundle.worker_cache),
                );
                self.device
                    .destroy_pipeline_cache(ok_bundle.worker_cache, None);
            }
            let prev_arc = self.active_psos.swap(Arc::new(ok_bundle.pso_set));
            self.retired_psos.push(RetiredPsoEntry {
                retire_after_timeline: self.timeline_counter,
                _pso_set: prev_arc,
            });
            self.async_pso_swaps_completed = self.async_pso_swaps_completed.saturating_add(1);
        }
        Ok(())
    }

    /// Uploads only modified bricks from `DirtyBrickQueue` (`<= 0.15ms` delta staging, `게임.md §8.1~§8.2`).
    pub fn stage_dirty_sdf_bricks(
        &mut self,
        world: &mut SparseSdfWorld,
        force_bootstrap_window: Option<(i32, i32)>,
    ) -> Result<u32, &'static str> {
        let mut dirty = world.drain_dirty_bricks();
        if let Some((center_bx, center_bz)) = force_bootstrap_window
            && self.staged_brick_coords.is_empty()
        {
            let mut bx = center_bx.saturating_sub(2);
            while bx <= center_bx.saturating_add(5) {
                let mut bz = center_bz.saturating_sub(2);
                while bz <= center_bz.saturating_add(5) {
                    let mut by: i32 = 0;
                    while by < 3 {
                        dirty.push(BrickCoord { bx, by, bz });
                        by = by.saturating_add(1);
                    }
                    bz = bz.saturating_add(1);
                }
                bx = bx.saturating_add(1);
            }
        }

        if dirty.is_empty() {
            return Ok(0);
        }

        let Some(hdr_alloc) = self.brick_headers_buf.allocation.as_mut() else {
            return Err("Missing brick_headers allocation");
        };
        let Some(cell_alloc) = self.sdf_cells_buf.allocation.as_mut() else {
            return Err("Missing sdf_cells allocation");
        };
        let hdr_bytes = hdr_alloc
            .mapped_slice_mut()
            .ok_or("brick_headers_buf not host-mapped")?;
        let cell_bytes = cell_alloc
            .mapped_slice_mut()
            .ok_or("sdf_cells_buf not host-mapped")?;

        let mut uploaded: u32 = 0;
        for coord in dirty {
            let slot_idx = match self.staged_brick_coords.iter().position(|&c| c == coord) {
                Some(existing) => existing,
                None => {
                    if self.staged_brick_coords.len() < MAX_GPU_BRICKS {
                        let idx = self.staged_brick_coords.len();
                        self.staged_brick_coords.push(coord);
                        idx
                    } else {
                        ((coord.bx.unsigned_abs() as usize)
                            .wrapping_mul(31)
                            .wrapping_add(coord.bz.unsigned_abs() as usize))
                            .checked_rem(MAX_GPU_BRICKS)
                            .unwrap_or(0)
                    }
                }
            };
            if slot_idx < self.staged_brick_coords.len() {
                self.staged_brick_coords[slot_idx] = coord;
            }

            let cell_base = slot_idx.saturating_mul(BRICK_CELL_COUNT);
            let hdr = BrickHeaderGpu {
                coord_and_flags: [coord.bx, coord.by, coord.bz, cell_base as i32],
            };
            let hdr_off = slot_idx.saturating_mul(core::mem::size_of::<BrickHeaderGpu>());
            Self::copy_pod_at(hdr_bytes, hdr_off, &hdr)?;

            let byte_base = cell_base.saturating_mul(4);
            let byte_end = byte_base.saturating_add(BRICK_CELL_COUNT.saturating_mul(4));
            if let Some(dst_brick) = cell_bytes.get_mut(byte_base..byte_end) {
                if let Some(brick) = world.brick(coord) {
                    let mut ci: usize = 0;
                    while ci < BRICK_CELL_COUNT {
                        let sdf_cm = i32::from(brick.sdf_cm[ci]);
                        let field = i32::from(brick.field_state[ci]);
                        let packed: i32 = (sdf_cm & 0xFFFF) | ((field & 0xFF) << 16);
                        let off = ci.saturating_mul(4);
                        if let Some(dst) = dst_brick.get_mut(off..off.saturating_add(4)) {
                            dst.copy_from_slice(&packed.to_le_bytes());
                        }
                        ci = ci.saturating_add(1);
                    }
                } else {
                    let empty_packed: [u8; 4] = (1000_i32 & 0xFFFF).to_le_bytes();
                    let mut ci: usize = 0;
                    while ci < BRICK_CELL_COUNT {
                        let off = ci.saturating_mul(4);
                        if let Some(dst) = dst_brick.get_mut(off..off.saturating_add(4)) {
                            dst.copy_from_slice(&empty_packed);
                        }
                        ci = ci.saturating_add(1);
                    }
                }
            }
            uploaded = uploaded.saturating_add(1);
        }

        Ok(uploaded)
    }

    /// Records & submits the full separated GPU hybrid frame (`sdf_world` -> `meshlet_cull_vis` ->
    /// `cmd_draw_indexed_indirect_count` -> `meshlet_cel` -> `radiance_cascades` -> `vfx_telegraph`),
    /// returning the `Timeline Semaphore` signal counter without stalling the CPU (`게임.md §8.2`).
    pub fn submit_hybrid_frame(
        &mut self,
        inputs: &HybridFrameInputs<'_>,
    ) -> Result<(u64, bool), &'static str> {
        self.submit_hybrid_frame_inner(inputs, false)
    }

    fn submit_hybrid_frame_inner(
        &mut self,
        inputs: &HybridFrameInputs<'_>,
        copy_to_readback: bool,
    ) -> Result<(u64, bool), &'static str> {
        let arena = inputs.arena;
        let player = inputs.player;
        let motion = inputs.motion;
        let time_sec_f32 = inputs.time_sec_f32;
        let hitstop_flash_permille = inputs.hitstop_flash_permille;
        let epoch_slot = inputs.epoch_slot;

        // 1. One-way `Q32.32 -> f32` conversion strictly for GPU Dual-Quaternion skinning & 3D camera (`게임.md §8.1`):
        let p_pos = arena.position(player).unwrap_or(QVec3::from_ints(8, 12, 8));
        let px = q32_to_f32(p_pos.x);
        let py = q32_to_f32(p_pos.y);
        let pz = q32_to_f32(p_pos.z);

        let mut boss_pos = [px + 6.0, py, pz + 6.0];
        let mut boss_shield_shattered = false;
        let mut telegraph_active: u32 = 0;
        let mut telegraph_kind: u32 = 0;
        if let Some(boss_id) = arena.first_alive_of_kind(EntityKind::Boss) {
            let bp = arena.position(boss_id).unwrap_or(p_pos);
            boss_pos = [q32_to_f32(bp.x), q32_to_f32(bp.y), q32_to_f32(bp.z)];
            let b_slot = boss_id.0 as usize;
            boss_shield_shattered = arena.shield[b_slot] <= Q32::ZERO;
            if arena.boss_telegraph_ticks[b_slot] > 0 {
                telegraph_active = 1;
                telegraph_kind = u32::from(arena.boss_pattern[b_slot] & 1);
            }
        }

        // 2. Multi-Bone Dual-Quaternion skinning palette (`§1.3`: per-joint `world_bone - rest_offset`,
        //    with joints `4..5` driven independently by `synthesize_foot_ik_world` `cosmetic_world_bones[0..1]`!):
        let mut dqs = [DualQuatGpu {
            q_real: [0.0, 0.0, 0.0, 1.0],
            q_dual: [0.0, 0.0, 0.0, 0.0],
        }; BONE_PALETTE_CAP];
        let mut bi: usize = 0;
        while bi < 6 {
            let wb = if bi == 4 {
                let ik_l = motion.cosmetic_world_bones[0];
                if ik_l == QVec3::ZERO {
                    motion.combat_world_bones[4]
                } else {
                    ik_l
                }
            } else if bi == 5 {
                let ik_r = motion.cosmetic_world_bones[1];
                if ik_r == QVec3::ZERO {
                    motion.combat_world_bones[5]
                } else {
                    ik_r
                }
            } else {
                motion.combat_world_bones[bi]
            };
            let rest = self.rest_joint_offsets[bi];
            let tx = q32_to_f32(wb.x) - rest[0];
            let ty = q32_to_f32(wb.y) - rest[1];
            let tz = q32_to_f32(wb.z) - rest[2];
            dqs[bi].q_dual = [0.5 * tx, 0.5 * ty, 0.5 * tz, 0.0];
            bi = bi.saturating_add(1);
        }

        let recoil = (hitstop_flash_permille as f32) * 0.0006;
        dqs[6].q_dual = [
            0.5 * (boss_pos[0] + recoil),
            0.5 * boss_pos[1],
            0.5 * (boss_pos[2] + recoil),
            0.0,
        ];
        if boss_shield_shattered {
            let half_ang = time_sec_f32 * 2.5;
            let (s_a, c_a) = half_ang.sin_cos();
            let tx = boss_pos[0] + 1.85;
            let ty = (boss_pos[1] - 0.6).max(1.0);
            let tz = boss_pos[2] + 1.25;
            dqs[7].q_real = [s_a, 0.0, 0.0, c_a];
            dqs[7].q_dual = [
                0.5 * tx * c_a,
                0.5 * (ty * c_a + tz * s_a),
                0.5 * (tz * c_a - ty * s_a),
                -0.5 * tx * s_a,
            ];
        } else {
            dqs[7].q_dual = [
                0.5 * boss_pos[0],
                0.5 * (boss_pos[1] + 1.4),
                0.5 * boss_pos[2],
                0.0,
            ];
        }
        Self::write_pod_slice(&self.skin_dq_buf, &dqs)?;

        // 3. 3D Orthonormal Camera Basis (`cam_yaw_turns` + `cam_pitch_turns` or `CameraOverride`):
        let aspect = (self.width as f32) / (self.height.max(1) as f32);
        let (cam_pos, fwd, right, up, tan_half_fov) = match inputs.camera_override {
            Some(ov) => (ov.pos, ov.forward, ov.right, ov.up, ov.tan_half_fov),
            None => {
                let sin_y = q32_to_f32(inputs.cam_yaw_turns.sin_turn());
                let cos_y = q32_to_f32(inputs.cam_yaw_turns.cos_turn());
                let pitch_rad =
                    (q32_to_f32(inputs.cam_pitch_turns) * core::f32::consts::TAU - 0.28).clamp(-1.05, 0.85);
                let (sin_p, cos_p) = pitch_rad.sin_cos();
                let f = [sin_y * cos_p, sin_p, cos_y * cos_p];
                let r = [cos_y, 0.0, -sin_y];
                let u = [-sin_y * sin_p, cos_p, -cos_y * sin_p];
                let c_pos = [
                    px - f[0] * 6.5,
                    (py + 1.6 - f[1] * 6.5).max(1.5),
                    pz - f[2] * 6.5,
                ];
                (c_pos, f, r, u, 0.577_350_26_f32)
            }
        };

        // 4. Genuine 3D Boss Telegraph AABB -> Screen Clip Projection (`CE-P1-02`):
        let active_cam = CameraOverride {
            pos: cam_pos,
            forward: fwd,
            right,
            up,
            tan_half_fov,
        };
        let mut telegraph_rect = [0_u32, 0, 16, 16];
        if telegraph_active != 0 {
            if let Some(proj_rect) = project_boss_telegraph_aabb(
                boss_pos,
                &active_cam,
                aspect,
                (self.width, self.height),
            ) {
                telegraph_rect = proj_rect;
            } else {
                telegraph_active = 0;
            }
        }

        // 5. Populate Live 64-bit BDA Scene Header & Translucent 3D Volumetric VFX Emitters (`CE-P1-02, CE-P1-04`):
        let pso_guard = self.active_psos.load();
        let mut vfx_emitters = [GpuVfxEmitter::default(); 8];
        let mut vfx_count: usize = 0;
        let phantasia_active = arena.first_alive_of_kind(EntityKind::Boss).is_some_and(|bid| {
            let bs = bid.0 as usize;
            bs < arena.time_scale.len() && arena.time_scale[bs] < Q32::ONE
        });
        if phantasia_active {
            vfx_emitters[vfx_count] = GpuVfxEmitter {
                center_and_radius: [px, py + 1.0, pz, 4.2],
                color_and_alpha: [0.22, 0.88, 1.40, 0.34],
            };
            vfx_count = vfx_count.saturating_add(1);
        }
        if hitstop_flash_permille > 0 && vfx_count < 8 {
            vfx_emitters[vfx_count] = GpuVfxEmitter {
                center_and_radius: [
                    0.5 * (px + boss_pos[0]),
                    0.5 * (py + boss_pos[1]) + 1.1,
                    0.5 * (pz + boss_pos[2]),
                    2.2,
                ],
                color_and_alpha: [1.55, 0.90, 0.24, 0.42],
            };
            vfx_count = vfx_count.saturating_add(1);
        }
        let mut ei: usize = 0;
        while ei < arena.alive.len() && vfx_count < 8 {
            if arena.alive[ei] != 0 && arena.kinds[ei] == (EntityKind::Projectile as u8) {
                vfx_emitters[vfx_count] = GpuVfxEmitter {
                    center_and_radius: [
                        q32_to_f32(arena.pos_x[ei]),
                        q32_to_f32(arena.pos_y[ei]),
                        q32_to_f32(arena.pos_z[ei]),
                        0.85,
                    ],
                    color_and_alpha: [0.35, 1.20, 1.65, 0.48],
                };
                vfx_count = vfx_count.saturating_add(1);
            }
            ei = ei.saturating_add(1);
        }

        let scene_hdr = GpuSceneBdaHeader {
            sun_dir_and_max_dist: [0.48, 0.78, -0.40, 140.0],
            sky_zenith_and_rough_cutoff: [0.032, 0.035, 0.042, 0.45],
            lut_and_vfx_counts: [
                0,
                vfx_count as u32,
                u32::from(pso_guard.use_64bit_vis_ssbo),
                self.width.saturating_add(7) >> 3,
            ],
            vfx_emitters,
        };
        Self::write_pod_slice(&self.scene_bda_buf, core::slice::from_ref(&scene_hdr))?;

        let push = FramePushConstants {
            cam_pos_and_fov: [cam_pos[0], cam_pos[1], cam_pos[2], tan_half_fov],
            cam_forward_and_time: [fwd[0], fwd[1], fwd[2], time_sec_f32],
            cam_right_and_aspect: [right[0], right[1], right[2], aspect],
            cam_up_and_near: [up[0], up[1], up[2], 0.15],
            viewport_and_flags: [
                self.width,
                self.height,
                self.staged_brick_coords.len() as u32,
                self.meshlet_count.max(1),
            ],
            telegraph_rect,
            telegraph_params: [
                telegraph_active,
                telegraph_kind,
                (self.width.min(self.height) >> 5).max(2),
                BONE_PALETTE_CAP as u32,
            ],
            scene_bda_address: self.scene_bda_buf.device_address,
            epoch_and_hitstop: [epoch_slot, hitstop_flash_permille],
        };

        let group_x = self.width.saturating_add(7) >> 3;
        let group_y = self.height.saturating_add(7) >> 3;

        // SAFETY: Single-in-flight command recording & submission synchronized via `Timeline Semaphore`.
        unsafe {
            self.device
                .reset_command_buffer(self.cmd_buf, vk::CommandBufferResetFlags::empty())
                .map_err(|_| "reset_command_buffer failed")?;
            let begin = vk::CommandBufferBeginInfo::default()
                .flags(vk::CommandBufferUsageFlags::ONE_TIME_SUBMIT);
            self.device
                .begin_command_buffer(self.cmd_buf, &begin)
                .map_err(|_| "begin_command_buffer failed")?;

            self.device.cmd_reset_query_pool(self.cmd_buf, self.query_pool, 0, 4);
            self.device.cmd_write_timestamp2(
                self.cmd_buf,
                vk::PipelineStageFlags2::TOP_OF_PIPE,
                self.query_pool,
                0,
            );

            let color_sub = vk::ImageSubresourceRange {
                aspect_mask: vk::ImageAspectFlags::COLOR,
                base_mip_level: 0,
                level_count: 1,
                base_array_layer: 0,
                layer_count: 1,
            };
            let depth_sub = vk::ImageSubresourceRange {
                aspect_mask: vk::ImageAspectFlags::DEPTH,
                base_mip_level: 0,
                level_count: 1,
                base_array_layer: 0,
                layer_count: 1,
            };

            let host_to_gpu = vk::MemoryBarrier2::default()
                .src_stage_mask(vk::PipelineStageFlags2::HOST)
                .src_access_mask(vk::AccessFlags2::HOST_WRITE)
                .dst_stage_mask(
                    vk::PipelineStageFlags2::COMPUTE_SHADER | vk::PipelineStageFlags2::VERTEX_SHADER,
                )
                .dst_access_mask(
                    vk::AccessFlags2::SHADER_READ | vk::AccessFlags2::SHADER_STORAGE_READ,
                );
            let init_img_bars = [
                vk::ImageMemoryBarrier2::default()
                    .src_stage_mask(vk::PipelineStageFlags2::TOP_OF_PIPE)
                    .src_access_mask(vk::AccessFlags2::NONE)
                    .dst_stage_mask(vk::PipelineStageFlags2::COMPUTE_SHADER)
                    .dst_access_mask(vk::AccessFlags2::SHADER_STORAGE_WRITE)
                    .old_layout(vk::ImageLayout::UNDEFINED)
                    .new_layout(vk::ImageLayout::GENERAL)
                    .image(self.out_color_img.image)
                    .subresource_range(color_sub),
                vk::ImageMemoryBarrier2::default()
                    .src_stage_mask(vk::PipelineStageFlags2::TOP_OF_PIPE)
                    .src_access_mask(vk::AccessFlags2::NONE)
                    .dst_stage_mask(
                        vk::PipelineStageFlags2::EARLY_FRAGMENT_TESTS
                            | vk::PipelineStageFlags2::LATE_FRAGMENT_TESTS,
                    )
                    .dst_access_mask(
                        vk::AccessFlags2::DEPTH_STENCIL_ATTACHMENT_READ
                            | vk::AccessFlags2::DEPTH_STENCIL_ATTACHMENT_WRITE,
                    )
                    .old_layout(vk::ImageLayout::UNDEFINED)
                    .new_layout(vk::ImageLayout::DEPTH_STENCIL_ATTACHMENT_OPTIMAL)
                    .image(self.vis_depth_img.image)
                    .subresource_range(depth_sub),
            ];
            self.device.cmd_pipeline_barrier2(
                self.cmd_buf,
                &vk::DependencyInfo::default()
                    .memory_barriers(core::slice::from_ref(&host_to_gpu))
                    .image_memory_barriers(&init_img_bars),
            );

            self.device.cmd_bind_descriptor_sets(
                self.cmd_buf,
                vk::PipelineBindPoint::COMPUTE,
                self.pipeline_layout,
                0,
                core::slice::from_ref(&self.desc_set),
                &[],
            );
            let push_bytes = core::slice::from_raw_parts(
                (&push as *const FramePushConstants).cast::<u8>(),
                core::mem::size_of::<FramePushConstants>(),
            );
            self.device.cmd_push_constants(
                self.cmd_buf,
                self.pipeline_layout,
                vk::ShaderStageFlags::COMPUTE
                    | vk::ShaderStageFlags::VERTEX
                    | vk::ShaderStageFlags::FRAGMENT,
                0,
                push_bytes,
            );

            let compute_mem_barrier = vk::MemoryBarrier2::default()
                .src_stage_mask(vk::PipelineStageFlags2::COMPUTE_SHADER)
                .src_access_mask(
                    vk::AccessFlags2::SHADER_WRITE | vk::AccessFlags2::SHADER_STORAGE_WRITE,
                )
                .dst_stage_mask(vk::PipelineStageFlags2::COMPUTE_SHADER)
                .dst_access_mask(
                    vk::AccessFlags2::SHADER_READ
                        | vk::AccessFlags2::SHADER_WRITE
                        | vk::AccessFlags2::SHADER_STORAGE_READ
                        | vk::AccessFlags2::SHADER_STORAGE_WRITE,
                );
            let dep_compute = vk::DependencyInfo::default()
                .memory_barriers(core::slice::from_ref(&compute_mem_barrier));

            if pso_guard.use_64bit_vis_ssbo {
                if !self.caps.draw_indirect_count {
                    // Zero-initialize `gIndirectCmds[0..max_indirect_draws]` so unfilled slots have
                    // `indexCount = 0, instanceCount = 0` when `vkCmdDrawIndexedIndirect` executes (`CE-P1-R2` item 3):
                    let fill_bytes = u64::from(self.max_indirect_draws)
                        .saturating_mul(core::mem::size_of::<DrawIndexedIndirectCmdGpu>() as u64);
                    self.device.cmd_fill_buffer(
                        self.cmd_buf,
                        self.indirect_cmds_buf.buffer,
                        0,
                        fill_bytes,
                        0,
                    );
                    let fill_to_comp = vk::MemoryBarrier2::default()
                        .src_stage_mask(vk::PipelineStageFlags2::CLEAR)
                        .src_access_mask(vk::AccessFlags2::TRANSFER_WRITE)
                        .dst_stage_mask(
                            vk::PipelineStageFlags2::COMPUTE_SHADER
                                | vk::PipelineStageFlags2::DRAW_INDIRECT,
                        )
                        .dst_access_mask(
                            vk::AccessFlags2::SHADER_STORAGE_WRITE
                                | vk::AccessFlags2::INDIRECT_COMMAND_READ,
                        );
                    self.device.cmd_pipeline_barrier2(
                        self.cmd_buf,
                        &vk::DependencyInfo::default()
                            .memory_barriers(core::slice::from_ref(&fill_to_comp)),
                    );
                }

                // Pass 1A: `sdf_world` -> 64-bit SSBO Visibility Buffer + Hi-Z Mip0/Mip1
                self.device.cmd_bind_pipeline(
                    self.cmd_buf,
                    vk::PipelineBindPoint::COMPUTE,
                    pso_guard.sdf_world_pso,
                );
                self.device.cmd_dispatch(self.cmd_buf, group_x, group_y, 1);
                self.device.cmd_pipeline_barrier2(self.cmd_buf, &dep_compute);

                // Pass 1B: `meshlet_cull_vis` -> Frustum/Cone/Hi-Z Culling + `<4x4px` Soft-Raster + `>=4x4px` Indirect Emit
                self.device.cmd_bind_pipeline(
                    self.cmd_buf,
                    vk::PipelineBindPoint::COMPUTE,
                    pso_guard.meshlet_cull_vis_pso,
                );
                self.device
                    .cmd_dispatch(self.cmd_buf, self.meshlet_count.max(1), 1, 1);

                let cull_to_indirect = vk::MemoryBarrier2::default()
                    .src_stage_mask(vk::PipelineStageFlags2::COMPUTE_SHADER)
                    .src_access_mask(
                        vk::AccessFlags2::SHADER_WRITE | vk::AccessFlags2::SHADER_STORAGE_WRITE,
                    )
                    .dst_stage_mask(
                        vk::PipelineStageFlags2::DRAW_INDIRECT
                            | vk::PipelineStageFlags2::INDEX_INPUT
                            | vk::PipelineStageFlags2::VERTEX_SHADER
                            | vk::PipelineStageFlags2::FRAGMENT_SHADER,
                    )
                    .dst_access_mask(
                        vk::AccessFlags2::INDIRECT_COMMAND_READ
                            | vk::AccessFlags2::INDEX_READ
                            | vk::AccessFlags2::SHADER_READ
                            | vk::AccessFlags2::SHADER_STORAGE_READ
                            | vk::AccessFlags2::SHADER_STORAGE_WRITE,
                    );
                self.device.cmd_pipeline_barrier2(
                    self.cmd_buf,
                    &vk::DependencyInfo::default()
                        .memory_barriers(core::slice::from_ref(&cull_to_indirect)),
                );

                // Pass 1C: `vis_indirect_gfx_pso` -> Reversed-Z Early-Z Hardware Indirect Raster (`>=4x4px` clusters)
                let d_att = vk::RenderingAttachmentInfo::default()
                    .image_view(self.vis_depth_img.view)
                    .image_layout(vk::ImageLayout::DEPTH_STENCIL_ATTACHMENT_OPTIMAL)
                    .load_op(vk::AttachmentLoadOp::CLEAR)
                    .store_op(vk::AttachmentStoreOp::STORE)
                    .clear_value(vk::ClearValue {
                        depth_stencil: vk::ClearDepthStencilValue {
                            depth: 0.0,
                            stencil: 0,
                        },
                    });
                let r_info = vk::RenderingInfo::default()
                    .render_area(vk::Rect2D {
                        offset: vk::Offset2D { x: 0, y: 0 },
                        extent: vk::Extent2D {
                            width: self.width,
                            height: self.height,
                        },
                    })
                    .layer_count(1)
                    .depth_attachment(&d_att);
                self.device.cmd_begin_rendering(self.cmd_buf, &r_info);
                self.device.cmd_bind_pipeline(
                    self.cmd_buf,
                    vk::PipelineBindPoint::GRAPHICS,
                    pso_guard.vis_indirect_gfx_pso,
                );
                self.device.cmd_bind_descriptor_sets(
                    self.cmd_buf,
                    vk::PipelineBindPoint::GRAPHICS,
                    self.pipeline_layout,
                    0,
                    core::slice::from_ref(&self.desc_set),
                    &[],
                );
                self.device.cmd_bind_index_buffer(
                    self.cmd_buf,
                    self.compacted_indices_buf.buffer,
                    0,
                    vk::IndexType::UINT32,
                );
                let vp = vk::Viewport {
                    x: 0.0,
                    y: 0.0,
                    width: self.width as f32,
                    height: self.height as f32,
                    min_depth: 0.0,
                    max_depth: 1.0,
                };
                let sc = vk::Rect2D {
                    offset: vk::Offset2D { x: 0, y: 0 },
                    extent: vk::Extent2D {
                        width: self.width,
                        height: self.height,
                    },
                };
                self.device
                    .cmd_set_viewport(self.cmd_buf, 0, core::slice::from_ref(&vp));
                self.device
                    .cmd_set_scissor(self.cmd_buf, 0, core::slice::from_ref(&sc));
                if self.caps.draw_indirect_count {
                    self.device.cmd_draw_indexed_indirect_count(
                        self.cmd_buf,
                        self.indirect_cmds_buf.buffer,
                        0,
                        self.indirect_count_buf.buffer,
                        0,
                        self.max_indirect_draws,
                        core::mem::size_of::<DrawIndexedIndirectCmdGpu>() as u32,
                    );
                } else {
                    self.device.cmd_draw_indexed_indirect(
                        self.cmd_buf,
                        self.indirect_cmds_buf.buffer,
                        0,
                        self.max_indirect_draws,
                        core::mem::size_of::<DrawIndexedIndirectCmdGpu>() as u32,
                    );
                }
                self.device.cmd_end_rendering(self.cmd_buf);

                self.device.cmd_write_timestamp2(
                    self.cmd_buf,
                    vk::PipelineStageFlags2::ALL_COMMANDS,
                    self.query_pool,
                    1,
                );

                let vis_to_shade = vk::MemoryBarrier2::default()
                    .src_stage_mask(
                        vk::PipelineStageFlags2::COMPUTE_SHADER
                            | vk::PipelineStageFlags2::FRAGMENT_SHADER
                            | vk::PipelineStageFlags2::EARLY_FRAGMENT_TESTS
                            | vk::PipelineStageFlags2::LATE_FRAGMENT_TESTS,
                    )
                    .src_access_mask(
                        vk::AccessFlags2::SHADER_WRITE
                            | vk::AccessFlags2::SHADER_STORAGE_WRITE
                            | vk::AccessFlags2::DEPTH_STENCIL_ATTACHMENT_WRITE,
                    )
                    .dst_stage_mask(vk::PipelineStageFlags2::COMPUTE_SHADER)
                    .dst_access_mask(
                        vk::AccessFlags2::SHADER_READ
                            | vk::AccessFlags2::SHADER_WRITE
                            | vk::AccessFlags2::SHADER_STORAGE_READ
                            | vk::AccessFlags2::SHADER_STORAGE_WRITE,
                    );
                self.device.cmd_pipeline_barrier2(
                    self.cmd_buf,
                    &vk::DependencyInfo::default()
                        .memory_barriers(core::slice::from_ref(&vis_to_shade)),
                );

                // Pass 2A: `meshlet_cel` — Overdraw-0% Single Compute Tile Material Resolve (`ddx`/`ddy` + Bindless KTX2 Mip)
                self.device.cmd_bind_pipeline(
                    self.cmd_buf,
                    vk::PipelineBindPoint::COMPUTE,
                    pso_guard.meshlet_cel_pso,
                );
                self.device.cmd_dispatch(self.cmd_buf, group_x, group_y, 1);
                self.device.cmd_pipeline_barrier2(self.cmd_buf, &dep_compute);
            } else if let Some(r_img) = &self.fallback_r32_img {
                // Core Fallback Path (`D32_SFLOAT + R32_UINT` Dynamic Rendering + `tile_shade_fallback`):
                let r_bar = vk::ImageMemoryBarrier2::default()
                    .src_stage_mask(vk::PipelineStageFlags2::TOP_OF_PIPE)
                    .dst_stage_mask(vk::PipelineStageFlags2::COLOR_ATTACHMENT_OUTPUT)
                    .dst_access_mask(vk::AccessFlags2::COLOR_ATTACHMENT_WRITE)
                    .old_layout(vk::ImageLayout::UNDEFINED)
                    .new_layout(vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL)
                    .image(r_img.image)
                    .subresource_range(color_sub);
                self.device.cmd_pipeline_barrier2(
                    self.cmd_buf,
                    &vk::DependencyInfo::default()
                        .image_memory_barriers(core::slice::from_ref(&r_bar)),
                );

                let c_att = vk::RenderingAttachmentInfo::default()
                    .image_view(r_img.view)
                    .image_layout(vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL)
                    .load_op(vk::AttachmentLoadOp::CLEAR)
                    .store_op(vk::AttachmentStoreOp::STORE)
                    .clear_value(vk::ClearValue {
                        color: vk::ClearColorValue { uint32: [0, 0, 0, 0] },
                    });
                let d_att = vk::RenderingAttachmentInfo::default()
                    .image_view(self.vis_depth_img.view)
                    .image_layout(vk::ImageLayout::DEPTH_STENCIL_ATTACHMENT_OPTIMAL)
                    .load_op(vk::AttachmentLoadOp::CLEAR)
                    .store_op(vk::AttachmentStoreOp::STORE)
                    .clear_value(vk::ClearValue {
                        depth_stencil: vk::ClearDepthStencilValue {
                            depth: 0.0,
                            stencil: 0,
                        },
                    });
                let r_info = vk::RenderingInfo::default()
                    .render_area(vk::Rect2D {
                        offset: vk::Offset2D { x: 0, y: 0 },
                        extent: vk::Extent2D {
                            width: self.width,
                            height: self.height,
                        },
                    })
                    .layer_count(1)
                    .color_attachments(core::slice::from_ref(&c_att))
                    .depth_attachment(&d_att);
                self.device.cmd_begin_rendering(self.cmd_buf, &r_info);
                self.device.cmd_bind_pipeline(
                    self.cmd_buf,
                    vk::PipelineBindPoint::GRAPHICS,
                    pso_guard.vis_fallback_gfx_pso,
                );
                self.device.cmd_bind_descriptor_sets(
                    self.cmd_buf,
                    vk::PipelineBindPoint::GRAPHICS,
                    self.pipeline_layout,
                    0,
                    core::slice::from_ref(&self.desc_set),
                    &[],
                );
                self.device.cmd_bind_index_buffer(
                    self.cmd_buf,
                    self.indices_buf.buffer,
                    0,
                    vk::IndexType::UINT32,
                );
                let vp = vk::Viewport {
                    x: 0.0,
                    y: 0.0,
                    width: self.width as f32,
                    height: self.height as f32,
                    min_depth: 0.0,
                    max_depth: 1.0,
                };
                let sc = vk::Rect2D {
                    offset: vk::Offset2D { x: 0, y: 0 },
                    extent: vk::Extent2D {
                        width: self.width,
                        height: self.height,
                    },
                };
                self.device
                    .cmd_set_viewport(self.cmd_buf, 0, core::slice::from_ref(&vp));
                self.device
                    .cmd_set_scissor(self.cmd_buf, 0, core::slice::from_ref(&sc));
                // Draw ALL meshlet clusters (`Player`, `Boss Core`, `Boss Crest`) and ALL triangles (`<= 124`/meshlet)
                // with exact `(clusterId, triId)` packed into `firstInstance` (`CE-P1-R2` item 2):
                for (cluster_id, ml) in self.cpu_meshlets.iter().enumerate() {
                    let tri_count = ml.counts_and_offs[1].min(124);
                    let vert_offset = ml.counts_and_offs[2] as i32;
                    let idx_base = ml.counts_and_offs[3];
                    let mut tri_id: u32 = 0;
                    while tri_id < tri_count {
                        let first_idx = idx_base.saturating_add(tri_id.saturating_mul(3));
                        let first_inst = 0x8000_0000_u32
                            | (((cluster_id as u32) & 0x7F_FFFF) << 8)
                            | (tri_id & 0xFF);
                        self.device.cmd_draw_indexed(
                            self.cmd_buf,
                            3,
                            1,
                            first_idx,
                            vert_offset,
                            first_inst,
                        );
                        tri_id = tri_id.saturating_add(1);
                    }
                }
                self.device.cmd_end_rendering(self.cmd_buf);

                self.device.cmd_write_timestamp2(
                    self.cmd_buf,
                    vk::PipelineStageFlags2::ALL_COMMANDS,
                    self.query_pool,
                    1,
                );

                let to_copy = vk::ImageMemoryBarrier2::default()
                    .src_stage_mask(vk::PipelineStageFlags2::COLOR_ATTACHMENT_OUTPUT)
                    .src_access_mask(vk::AccessFlags2::COLOR_ATTACHMENT_WRITE)
                    .dst_stage_mask(vk::PipelineStageFlags2::COPY)
                    .dst_access_mask(vk::AccessFlags2::TRANSFER_READ)
                    .old_layout(vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL)
                    .new_layout(vk::ImageLayout::TRANSFER_SRC_OPTIMAL)
                    .image(r_img.image)
                    .subresource_range(color_sub);
                self.device.cmd_pipeline_barrier2(
                    self.cmd_buf,
                    &vk::DependencyInfo::default()
                        .image_memory_barriers(core::slice::from_ref(&to_copy)),
                );
                let region = vk::BufferImageCopy {
                    buffer_offset: 0,
                    buffer_row_length: 0,
                    buffer_image_height: 0,
                    image_subresource: vk::ImageSubresourceLayers {
                        aspect_mask: vk::ImageAspectFlags::COLOR,
                        mip_level: 0,
                        base_array_layer: 0,
                        layer_count: 1,
                    },
                    image_offset: vk::Offset3D { x: 0, y: 0, z: 0 },
                    image_extent: vk::Extent3D {
                        width: self.width,
                        height: self.height,
                        depth: 1,
                    },
                };
                self.device.cmd_copy_image_to_buffer(
                    self.cmd_buf,
                    r_img.image,
                    vk::ImageLayout::TRANSFER_SRC_OPTIMAL,
                    self.vis_r32_fallback_buf.buffer,
                    core::slice::from_ref(&region),
                );
                let copy_to_comp = vk::MemoryBarrier2::default()
                    .src_stage_mask(vk::PipelineStageFlags2::COPY)
                    .src_access_mask(vk::AccessFlags2::TRANSFER_WRITE)
                    .dst_stage_mask(vk::PipelineStageFlags2::COMPUTE_SHADER)
                    .dst_access_mask(
                        vk::AccessFlags2::SHADER_READ | vk::AccessFlags2::SHADER_STORAGE_READ,
                    );
                self.device.cmd_pipeline_barrier2(
                    self.cmd_buf,
                    &vk::DependencyInfo::default()
                        .memory_barriers(core::slice::from_ref(&copy_to_comp)),
                );
                self.device.cmd_bind_pipeline(
                    self.cmd_buf,
                    vk::PipelineBindPoint::COMPUTE,
                    pso_guard.tile_shade_fallback_pso,
                );
                self.device.cmd_dispatch(self.cmd_buf, group_x, group_y, 1);
                self.device.cmd_pipeline_barrier2(self.cmd_buf, &dep_compute);
            }

            // Pass 2B: `radiance_cascades` — 3D Sparse Radiance Cascades GI + Screen `Hi-Z` / World `SDF` Specular
            self.device.cmd_bind_pipeline(
                self.cmd_buf,
                vk::PipelineBindPoint::COMPUTE,
                pso_guard.radiance_cascades_pso,
            );
            self.device.cmd_dispatch(self.cmd_buf, group_x, group_y, 1);
            self.device.cmd_pipeline_barrier2(self.cmd_buf, &dep_compute);

            self.device.cmd_write_timestamp2(
                self.cmd_buf,
                vk::PipelineStageFlags2::COMPUTE_SHADER,
                self.query_pool,
                2,
            );

            // Pass 3: `vfx_telegraph` — Translucent 3D VFX + ACES Tonemap + Orthogonal OKLab Telegraph & Dual Outline
            self.device.cmd_bind_pipeline(
                self.cmd_buf,
                vk::PipelineBindPoint::COMPUTE,
                pso_guard.vfx_telegraph_pso,
            );
            self.device.cmd_dispatch(self.cmd_buf, group_x, group_y, 1);

            self.device.cmd_write_timestamp2(
                self.cmd_buf,
                vk::PipelineStageFlags2::COMPUTE_SHADER,
                self.query_pool,
                3,
            );

            if copy_to_readback {
                let to_xfer = vk::ImageMemoryBarrier2::default()
                    .src_stage_mask(vk::PipelineStageFlags2::COMPUTE_SHADER)
                    .src_access_mask(vk::AccessFlags2::SHADER_STORAGE_WRITE)
                    .dst_stage_mask(vk::PipelineStageFlags2::COPY)
                    .dst_access_mask(vk::AccessFlags2::TRANSFER_READ)
                    .old_layout(vk::ImageLayout::GENERAL)
                    .new_layout(vk::ImageLayout::TRANSFER_SRC_OPTIMAL)
                    .image(self.out_color_img.image)
                    .subresource_range(color_sub);
                self.device.cmd_pipeline_barrier2(
                    self.cmd_buf,
                    &vk::DependencyInfo::default()
                        .image_memory_barriers(core::slice::from_ref(&to_xfer)),
                );
                let region = vk::BufferImageCopy {
                    buffer_offset: 0,
                    buffer_row_length: 0,
                    buffer_image_height: 0,
                    image_subresource: vk::ImageSubresourceLayers {
                        aspect_mask: vk::ImageAspectFlags::COLOR,
                        mip_level: 0,
                        base_array_layer: 0,
                        layer_count: 1,
                    },
                    image_offset: vk::Offset3D { x: 0, y: 0, z: 0 },
                    image_extent: vk::Extent3D {
                        width: self.width,
                        height: self.height,
                        depth: 1,
                    },
                };
                self.device.cmd_copy_image_to_buffer(
                    self.cmd_buf,
                    self.out_color_img.image,
                    vk::ImageLayout::TRANSFER_SRC_OPTIMAL,
                    self.readback_buf.buffer,
                    core::slice::from_ref(&region),
                );
                let xfer_to_host = vk::BufferMemoryBarrier2::default()
                    .src_stage_mask(vk::PipelineStageFlags2::COPY)
                    .src_access_mask(vk::AccessFlags2::TRANSFER_WRITE)
                    .dst_stage_mask(vk::PipelineStageFlags2::HOST)
                    .dst_access_mask(vk::AccessFlags2::HOST_READ)
                    .buffer(self.readback_buf.buffer)
                    .offset(0)
                    .size(vk::WHOLE_SIZE);
                self.device.cmd_pipeline_barrier2(
                    self.cmd_buf,
                    &vk::DependencyInfo::default()
                        .buffer_memory_barriers(core::slice::from_ref(&xfer_to_host)),
                );
            }

            self.device
                .end_command_buffer(self.cmd_buf)
                .map_err(|_| "end_command_buffer failed")?;

            // Single-in-flight Timeline Semaphore Submit (`0` multi-frame queue latency!):
            self.timeline_counter = self.timeline_counter.saturating_add(1);
            let signal_val = self.timeline_counter;
            let cb_submit = vk::CommandBufferSubmitInfo::default().command_buffer(self.cmd_buf);
            let sig_submit = vk::SemaphoreSubmitInfo::default()
                .semaphore(self.timeline_sem)
                .value(signal_val)
                .stage_mask(vk::PipelineStageFlags2::ALL_COMMANDS);
            let submit2 = vk::SubmitInfo2::default()
                .command_buffer_infos(core::slice::from_ref(&cb_submit))
                .signal_semaphore_infos(core::slice::from_ref(&sig_submit));

            self.device
                .queue_submit2(self.queue, core::slice::from_ref(&submit2), vk::Fence::null())
                .map_err(|_| "vkQueueSubmit2 failed")?;

            Ok((signal_val, pso_guard.use_64bit_vis_ssbo))
        }
    }

    /// Waits on the single-in-flight `Timeline Semaphore` counter (`0` multi-frame queue latency),
    /// presents to `winit` swapchain (+ `VK_KHR_present_wait`) when `present_to_window == true`,
    /// and reads hardware `VkQueryPool` pass timestamps (`게임.md §8.2`).
    pub fn wait_frame_gpu_timings(
        &mut self,
        signal_val: u64,
        used_64bit_vis_ssbo: bool,
        present_to_window: bool,
    ) -> Result<GpuFrameTimingsNs, &'static str> {
        // SAFETY: Waits on valid `timeline_sem` value submitted by `submit_hybrid_frame` and reads completed query pool.
        unsafe {
            let wait_info = vk::SemaphoreWaitInfo::default()
                .semaphores(core::slice::from_ref(&self.timeline_sem))
                .values(core::slice::from_ref(&signal_val));
            self.device
                .wait_semaphores(&wait_info, u64::MAX)
                .map_err(|_| "vkWaitSemaphores(TIMELINE) failed")?;

            let mut ts = [0_u64; 4];
            self.device
                .get_query_pool_results(
                    self.query_pool,
                    0,
                    &mut ts,
                    vk::QueryResultFlags::TYPE_64 | vk::QueryResultFlags::WAIT,
                )
                .map_err(|_| "get_query_pool_results failed")?;

            if present_to_window {
                self.present_if_window_active();
            }

            let to_ns = |a: u64, b: u64| -> u64 {
                let ticks = b.saturating_sub(a) as f64;
                (ticks * self.timestamp_period_ns) as u64
            };

            Ok(GpuFrameTimingsNs {
                vis_cull_ns: to_ns(ts[0], ts[1]),
                cel_gi_ns: to_ns(ts[1], ts[2]),
                vfx_telegraph_ns: to_ns(ts[2], ts[3]),
                total_gpu_ns: to_ns(ts[0], ts[3]),
                used_64bit_vis_ssbo,
                active_bricks_uploaded: self.staged_brick_coords.len() as u32,
            })
        }
    }

    /// Convenience wrapper recording, submitting, and synchronizing a complete hybrid frame.
    pub fn render_hybrid_frame(
        &mut self,
        inputs: &HybridFrameInputs<'_>,
    ) -> Result<GpuFrameTimingsNs, &'static str> {
        let (sig, used_64) = self.submit_hybrid_frame(inputs)?;
        self.wait_frame_gpu_timings(sig, used_64, inputs.present_to_window)
    }

    /// Executes the full hybrid frame on GPU and copies the resulting RGBA8 pixels into `out_rgba`.
    pub fn render_hybrid_frame_and_readback(
        &mut self,
        inputs: &HybridFrameInputs<'_>,
        out_rgba: &mut [u8],
    ) -> Result<GpuFrameTimingsNs, &'static str> {
        let (sig, used_64) = self.submit_hybrid_frame_inner(inputs, true)?;
        let timings = self.wait_frame_gpu_timings(sig, used_64, false)?;
        let Some(rb_alloc) = self.readback_buf.allocation.as_ref() else {
            return Err("Missing readback_buf allocation");
        };
        let mapped = rb_alloc
            .mapped_slice()
            .ok_or("readback_buf is not host-mapped")?;
        let copy_len = out_rgba.len().min(mapped.len());
        out_rgba[..copy_len].copy_from_slice(&mapped[..copy_len]);
        Ok(timings)
    }

    unsafe fn present_if_window_active(&mut self) {
        let Some(mut pres) = self.presenter.take() else {
            return;
        };
        // SAFETY: Non-blocking swapchain blit + `VK_KHR_present_id` / `VK_KHR_present_wait` frame pacing.
        unsafe {
            let Ok((img_idx, _)) = pres.swapchain_loader.acquire_next_image(
                pres.swapchain,
                2_000_000,
                pres.acquire_sem,
                vk::Fence::null(),
            ) else {
                self.presenter = Some(pres);
                return;
            };
            let Some(&dst_img) = pres.images.get(img_idx as usize) else {
                self.presenter = Some(pres);
                return;
            };
            if self
                .device
                .reset_command_buffer(self.cmd_buf, vk::CommandBufferResetFlags::empty())
                .is_err()
            {
                self.presenter = Some(pres);
                return;
            }
            let begin = vk::CommandBufferBeginInfo::default()
                .flags(vk::CommandBufferUsageFlags::ONE_TIME_SUBMIT);
            if self.device.begin_command_buffer(self.cmd_buf, &begin).is_err() {
                self.presenter = Some(pres);
                return;
            }
            let sub = vk::ImageSubresourceRange {
                aspect_mask: vk::ImageAspectFlags::COLOR,
                base_mip_level: 0,
                level_count: 1,
                base_array_layer: 0,
                layer_count: 1,
            };
            let bars_in = [
                vk::ImageMemoryBarrier2::default()
                    .src_stage_mask(vk::PipelineStageFlags2::COMPUTE_SHADER)
                    .src_access_mask(vk::AccessFlags2::SHADER_STORAGE_WRITE)
                    .dst_stage_mask(vk::PipelineStageFlags2::BLIT)
                    .dst_access_mask(vk::AccessFlags2::TRANSFER_READ)
                    .old_layout(vk::ImageLayout::GENERAL)
                    .new_layout(vk::ImageLayout::TRANSFER_SRC_OPTIMAL)
                    .image(self.out_color_img.image)
                    .subresource_range(sub),
                vk::ImageMemoryBarrier2::default()
                    .src_stage_mask(vk::PipelineStageFlags2::TOP_OF_PIPE)
                    .dst_stage_mask(vk::PipelineStageFlags2::BLIT)
                    .dst_access_mask(vk::AccessFlags2::TRANSFER_WRITE)
                    .old_layout(vk::ImageLayout::UNDEFINED)
                    .new_layout(vk::ImageLayout::TRANSFER_DST_OPTIMAL)
                    .image(dst_img)
                    .subresource_range(sub),
            ];
            self.device.cmd_pipeline_barrier2(
                self.cmd_buf,
                &vk::DependencyInfo::default().image_memory_barriers(&bars_in),
            );
            let blit = vk::ImageBlit {
                src_subresource: vk::ImageSubresourceLayers {
                    aspect_mask: vk::ImageAspectFlags::COLOR,
                    mip_level: 0,
                    base_array_layer: 0,
                    layer_count: 1,
                },
                src_offsets: [
                    vk::Offset3D { x: 0, y: 0, z: 0 },
                    vk::Offset3D {
                        x: self.width as i32,
                        y: self.height as i32,
                        z: 1,
                    },
                ],
                dst_subresource: vk::ImageSubresourceLayers {
                    aspect_mask: vk::ImageAspectFlags::COLOR,
                    mip_level: 0,
                    base_array_layer: 0,
                    layer_count: 1,
                },
                dst_offsets: [
                    vk::Offset3D { x: 0, y: 0, z: 0 },
                    vk::Offset3D {
                        x: pres.extent.width as i32,
                        y: pres.extent.height as i32,
                        z: 1,
                    },
                ],
            };
            self.device.cmd_blit_image(
                self.cmd_buf,
                self.out_color_img.image,
                vk::ImageLayout::TRANSFER_SRC_OPTIMAL,
                dst_img,
                vk::ImageLayout::TRANSFER_DST_OPTIMAL,
                core::slice::from_ref(&blit),
                vk::Filter::LINEAR,
            );
            let to_pres = vk::ImageMemoryBarrier2::default()
                .src_stage_mask(vk::PipelineStageFlags2::BLIT)
                .src_access_mask(vk::AccessFlags2::TRANSFER_WRITE)
                .dst_stage_mask(vk::PipelineStageFlags2::BOTTOM_OF_PIPE)
                .old_layout(vk::ImageLayout::TRANSFER_DST_OPTIMAL)
                .new_layout(vk::ImageLayout::PRESENT_SRC_KHR)
                .image(dst_img)
                .subresource_range(sub);
            self.device.cmd_pipeline_barrier2(
                self.cmd_buf,
                &vk::DependencyInfo::default()
                    .image_memory_barriers(core::slice::from_ref(&to_pres)),
            );
            if self.device.end_command_buffer(self.cmd_buf).is_err() {
                self.presenter = Some(pres);
                return;
            }
            self.timeline_counter = self.timeline_counter.saturating_add(1);
            let sig_t = self.timeline_counter;
            let wait_s = vk::SemaphoreSubmitInfo::default()
                .semaphore(pres.acquire_sem)
                .stage_mask(vk::PipelineStageFlags2::BLIT);
            let sigs = [
                vk::SemaphoreSubmitInfo::default()
                    .semaphore(pres.present_sem)
                    .stage_mask(vk::PipelineStageFlags2::ALL_COMMANDS),
                vk::SemaphoreSubmitInfo::default()
                    .semaphore(self.timeline_sem)
                    .value(sig_t)
                    .stage_mask(vk::PipelineStageFlags2::ALL_COMMANDS),
            ];
            let cbi = vk::CommandBufferSubmitInfo::default().command_buffer(self.cmd_buf);
            let sub2 = vk::SubmitInfo2::default()
                .wait_semaphore_infos(core::slice::from_ref(&wait_s))
                .command_buffer_infos(core::slice::from_ref(&cbi))
                .signal_semaphore_infos(&sigs);
            if self
                .device
                .queue_submit2(self.queue, core::slice::from_ref(&sub2), vk::Fence::null())
                .is_ok()
            {
                pres.present_serial = pres.present_serial.saturating_add(1);
                let pid = pres.present_serial;
                let mut present_id_info =
                    vk::PresentIdKHR::default().present_ids(core::slice::from_ref(&pid));
                let mut p_info = vk::PresentInfoKHR::default()
                    .wait_semaphores(core::slice::from_ref(&pres.present_sem))
                    .swapchains(core::slice::from_ref(&pres.swapchain))
                    .image_indices(core::slice::from_ref(&img_idx));
                if pres.present_wait_loader.is_some() {
                    p_info = p_info.push_next(&mut present_id_info);
                }
                let pres_ok = pres.swapchain_loader.queue_present(self.queue, &p_info).is_ok();
                if pres_ok
                    && let Some(pw) = pres.present_wait_loader.as_ref()
                {
                    let _ = pw.wait_for_present(pres.swapchain, pid, 5_000_000);
                }
                let w_info = vk::SemaphoreWaitInfo::default()
                    .semaphores(core::slice::from_ref(&self.timeline_sem))
                    .values(core::slice::from_ref(&sig_t));
                let _ = self.device.wait_semaphores(&w_info, u64::MAX);
            }
        }
        self.presenter = Some(pres);
    }

    unsafe fn compile_pso_bundle(
        device: &ash::Device,
        layout: vk::PipelineLayout,
        cache: vk::PipelineCache,
        caps: &HardwareVulkanCaps,
    ) -> Result<CompiledPsoSet, &'static str> {
        // SAFETY: Validates SPIR-V capabilities strictly before calling `create_shader_module`.
        unsafe {
            let make_comp = |words: &[u32]| -> Result<vk::Pipeline, &'static str> {
                verify_spirv_capabilities(words, caps)?;
                let sm_info = vk::ShaderModuleCreateInfo::default().code(words);
                let sm = device
                    .create_shader_module(&sm_info, None)
                    .map_err(|_| "create_shader_module failed")?;
                let stage = vk::PipelineShaderStageCreateInfo::default()
                    .stage(vk::ShaderStageFlags::COMPUTE)
                    .module(sm)
                    .name(c"main");
                let cp_info = vk::ComputePipelineCreateInfo::default()
                    .stage(stage)
                    .layout(layout);
                let res = device.create_compute_pipelines(cache, core::slice::from_ref(&cp_info), None);
                device.destroy_shader_module(sm, None);
                match res {
                    Ok(v) => v.into_iter().next().ok_or("Empty compute pipeline result"),
                    Err((_, _)) => Err("create_compute_pipelines failed"),
                }
            };

            let make_gfx = |vs_words: &[u32],
                            fs_words: &[u32],
                            color_fmts: &[vk::Format]|
             -> Result<vk::Pipeline, &'static str> {
                verify_spirv_capabilities(vs_words, caps)?;
                verify_spirv_capabilities(fs_words, caps)?;
                let vs_mod = device
                    .create_shader_module(&vk::ShaderModuleCreateInfo::default().code(vs_words), None)
                    .map_err(|_| "vs module failed")?;
                let fs_mod = device
                    .create_shader_module(&vk::ShaderModuleCreateInfo::default().code(fs_words), None)
                    .map_err(|_| "fs module failed")?;
                let stages = [
                    vk::PipelineShaderStageCreateInfo::default()
                        .stage(vk::ShaderStageFlags::VERTEX)
                        .module(vs_mod)
                        .name(c"main"),
                    vk::PipelineShaderStageCreateInfo::default()
                        .stage(vk::ShaderStageFlags::FRAGMENT)
                        .module(fs_mod)
                        .name(c"main"),
                ];
                let vi = vk::PipelineVertexInputStateCreateInfo::default();
                let ia = vk::PipelineInputAssemblyStateCreateInfo::default()
                    .topology(vk::PrimitiveTopology::TRIANGLE_LIST);
                let vp_state = vk::PipelineViewportStateCreateInfo::default()
                    .viewport_count(1)
                    .scissor_count(1);
                let rast = vk::PipelineRasterizationStateCreateInfo::default()
                    .polygon_mode(vk::PolygonMode::FILL)
                    .cull_mode(vk::CullModeFlags::NONE)
                    .line_width(1.0);
                let ms = vk::PipelineMultisampleStateCreateInfo::default()
                    .rasterization_samples(vk::SampleCountFlags::TYPE_1);
                let ds = vk::PipelineDepthStencilStateCreateInfo::default()
                    .depth_test_enable(true)
                    .depth_write_enable(true)
                    .depth_compare_op(vk::CompareOp::GREATER_OR_EQUAL); // Reversed-Z!
                let blend_atts: Vec<vk::PipelineColorBlendAttachmentState> = color_fmts
                    .iter()
                    .map(|_| {
                        vk::PipelineColorBlendAttachmentState::default()
                            .color_write_mask(vk::ColorComponentFlags::RGBA)
                    })
                    .collect();
                let cb = vk::PipelineColorBlendStateCreateInfo::default().attachments(&blend_atts);
                let dyn_states = [vk::DynamicState::VIEWPORT, vk::DynamicState::SCISSOR];
                let dyn_info =
                    vk::PipelineDynamicStateCreateInfo::default().dynamic_states(&dyn_states);
                let mut rendering_info = vk::PipelineRenderingCreateInfo::default()
                    .color_attachment_formats(color_fmts)
                    .depth_attachment_format(vk::Format::D32_SFLOAT);

                let gp_info = vk::GraphicsPipelineCreateInfo::default()
                    .stages(&stages)
                    .vertex_input_state(&vi)
                    .input_assembly_state(&ia)
                    .viewport_state(&vp_state)
                    .rasterization_state(&rast)
                    .multisample_state(&ms)
                    .depth_stencil_state(&ds)
                    .color_blend_state(&cb)
                    .dynamic_state(&dyn_info)
                    .layout(layout)
                    .push_next(&mut rendering_info);
                let gfx_res =
                    device.create_graphics_pipelines(cache, core::slice::from_ref(&gp_info), None);
                device.destroy_shader_module(vs_mod, None);
                device.destroy_shader_module(fs_mod, None);
                match gfx_res {
                    Ok(v) => v.into_iter().next().ok_or("Empty graphics PSO"),
                    Err((_, _)) => Err("create_graphics_pipelines failed"),
                }
            };

            let can_use_primary_64 = caps.shader_int64
                && caps.shader_int64_atomics
                && caps.buffer_device_address
                && caps.sampled_image_non_uniform
                && caps.fragment_stores_and_atomics
                && caps.draw_parameters;

            if can_use_primary_64 {
                let sdf_world_pso = make_comp(&SPV_SDF_WORLD)?;
                let meshlet_cull_vis_pso = make_comp(&SPV_MESHLET_CULL_VIS)?;
                let vis_indirect_gfx_pso = make_gfx(&SPV_VIS_INDIRECT_VS, &SPV_VIS_INDIRECT_FS, &[])?;
                let meshlet_cel_pso = make_comp(&SPV_MESHLET_CEL)?;
                let radiance_cascades_pso = make_comp(&SPV_RADIANCE_CASCADES)?;
                let vfx_telegraph_pso = make_comp(&SPV_VFX_TELEGRAPH)?;
                Ok(CompiledPsoSet {
                    device: device.clone(),
                    use_64bit_vis_ssbo: true,
                    sdf_world_pso,
                    meshlet_cull_vis_pso,
                    vis_indirect_gfx_pso,
                    meshlet_cel_pso,
                    radiance_cascades_pso,
                    vfx_telegraph_pso,
                    vis_fallback_gfx_pso: vk::Pipeline::null(),
                    tile_shade_fallback_pso: vk::Pipeline::null(),
                })
            } else {
                let vis_fallback_gfx_pso = make_gfx(
                    &SPV_VIS_FALLBACK_VS,
                    &SPV_VIS_FALLBACK_FS,
                    &[vk::Format::R32_UINT],
                )?;
                let tile_shade_fallback_pso = make_comp(&SPV_TILE_SHADE_FALLBACK)?;
                let radiance_cascades_pso = make_comp(&SPV_RADIANCE_CASCADES_FALLBACK)?;
                let vfx_telegraph_pso = make_comp(&SPV_VFX_TELEGRAPH_FALLBACK)?;
                Ok(CompiledPsoSet {
                    device: device.clone(),
                    use_64bit_vis_ssbo: false,
                    sdf_world_pso: vk::Pipeline::null(),
                    meshlet_cull_vis_pso: vk::Pipeline::null(),
                    vis_indirect_gfx_pso: vk::Pipeline::null(),
                    meshlet_cel_pso: vk::Pipeline::null(),
                    radiance_cascades_pso,
                    vfx_telegraph_pso,
                    vis_fallback_gfx_pso,
                    tile_shade_fallback_pso,
                })
            }
        }
    }

    unsafe fn upload_ktx2_mips(
        inst_and_dev: (&ash::Instance, &ash::Device),
        alloc: &mut Allocator,
        xfer_ctx: (vk::Queue, vk::CommandBuffer, vk::Semaphore, &mut u64),
        image: vk::Image,
        mips: &[Ktx2MipLevel],
        try_host_image_copy: bool,
    ) -> Result<bool, &'static str> {
        let (instance, device) = inst_and_dev;
        let (queue, cmd_buf, timeline_sem, timeline_counter) = xfer_ctx;
        let mip_count = mips.len().max(1) as u32;

        // 1. Primary Vulkan 1.4 / `VK_EXT_host_image_copy` zero-staging direct CPU->GPU image upload:
        if try_host_image_copy && !mips.is_empty() {
            // SAFETY: `VK_EXT_host_image_copy` feature & `HOST_TRANSFER_EXT` usage verified prior to call.
            unsafe {
                let hic_dev = ash::ext::host_image_copy::Device::new(instance, device);
                let trans = vk::HostImageLayoutTransitionInfoEXT::default()
                    .image(image)
                    .old_layout(vk::ImageLayout::UNDEFINED)
                    .new_layout(vk::ImageLayout::SHADER_READ_ONLY_OPTIMAL)
                    .subresource_range(vk::ImageSubresourceRange {
                        aspect_mask: vk::ImageAspectFlags::COLOR,
                        base_mip_level: 0,
                        level_count: mip_count,
                        base_array_layer: 0,
                        layer_count: 1,
                    });
                if hic_dev
                    .transition_image_layout(core::slice::from_ref(&trans))
                    .is_ok()
                {
                    let mut regions: Vec<vk::MemoryToImageCopyEXT<'_>> =
                        Vec::with_capacity(mips.len());
                    for (mi, mip) in mips.iter().enumerate() {
                        regions.push(
                            vk::MemoryToImageCopyEXT::default()
                                .host_pointer(mip.rgba_bytes.as_ptr().cast::<c_void>())
                                .image_subresource(vk::ImageSubresourceLayers {
                                    aspect_mask: vk::ImageAspectFlags::COLOR,
                                    mip_level: mi as u32,
                                    base_array_layer: 0,
                                    layer_count: 1,
                                })
                                .image_extent(vk::Extent3D {
                                    width: mip.width,
                                    height: mip.height,
                                    depth: 1,
                                }),
                        );
                    }
                    let copy_info = vk::CopyMemoryToImageInfoEXT::default()
                        .dst_image(image)
                        .dst_image_layout(vk::ImageLayout::SHADER_READ_ONLY_OPTIMAL)
                        .regions(&regions);
                    if hic_dev.copy_memory_to_image(&copy_info).is_ok() {
                        return Ok(true);
                    }
                }
            }
        }

        // 2. Automatic Vulkan 1.3 Staging `vkCmdCopyBufferToImage` Fallback:
        let mut total_bytes: usize = 0;
        for mip in mips {
            total_bytes = total_bytes.saturating_add(mip.rgba_bytes.len());
        }
        // SAFETY: One-shot staging buffer upload synchronized via `timeline_sem` before freeing staging buffer.
        unsafe {
            let mut staging = Self::alloc_buffer_ext(
                device,
                alloc,
                "ktx2_staging_buf",
                total_bytes.max(64) as u64,
                MemoryLocation::CpuToGpu,
                vk::BufferUsageFlags::TRANSFER_SRC,
                false,
            )?;
            let mut copy_regions: Vec<vk::BufferImageCopy> = Vec::with_capacity(mips.len());
            if let Some(st_alloc) = staging.allocation.as_mut()
                && let Some(dst) = st_alloc.mapped_slice_mut()
            {
                let mut cur_off: usize = 0;
                for (mi, mip) in mips.iter().enumerate() {
                    let end = cur_off.saturating_add(mip.rgba_bytes.len());
                    if let Some(slice) = dst.get_mut(cur_off..end) {
                        slice.copy_from_slice(&mip.rgba_bytes);
                        copy_regions.push(vk::BufferImageCopy {
                            buffer_offset: cur_off as u64,
                            buffer_row_length: 0,
                            buffer_image_height: 0,
                            image_subresource: vk::ImageSubresourceLayers {
                                aspect_mask: vk::ImageAspectFlags::COLOR,
                                mip_level: mi as u32,
                                base_array_layer: 0,
                                layer_count: 1,
                            },
                            image_offset: vk::Offset3D { x: 0, y: 0, z: 0 },
                            image_extent: vk::Extent3D {
                                width: mip.width,
                                height: mip.height,
                                depth: 1,
                            },
                        });
                    }
                    cur_off = end;
                }
            }

            device
                .reset_command_buffer(cmd_buf, vk::CommandBufferResetFlags::empty())
                .map_err(|_| "ktx2 reset_command_buffer failed")?;
            device
                .begin_command_buffer(
                    cmd_buf,
                    &vk::CommandBufferBeginInfo::default()
                        .flags(vk::CommandBufferUsageFlags::ONE_TIME_SUBMIT),
                )
                .map_err(|_| "ktx2 begin_command_buffer failed")?;
            let sub = vk::ImageSubresourceRange {
                aspect_mask: vk::ImageAspectFlags::COLOR,
                base_mip_level: 0,
                level_count: mip_count,
                base_array_layer: 0,
                layer_count: 1,
            };
            let to_dst = vk::ImageMemoryBarrier2::default()
                .src_stage_mask(vk::PipelineStageFlags2::TOP_OF_PIPE)
                .dst_stage_mask(vk::PipelineStageFlags2::COPY)
                .dst_access_mask(vk::AccessFlags2::TRANSFER_WRITE)
                .old_layout(vk::ImageLayout::UNDEFINED)
                .new_layout(vk::ImageLayout::TRANSFER_DST_OPTIMAL)
                .image(image)
                .subresource_range(sub);
            device.cmd_pipeline_barrier2(
                cmd_buf,
                &vk::DependencyInfo::default()
                    .image_memory_barriers(core::slice::from_ref(&to_dst)),
            );
            if !copy_regions.is_empty() {
                device.cmd_copy_buffer_to_image(
                    cmd_buf,
                    staging.buffer,
                    image,
                    vk::ImageLayout::TRANSFER_DST_OPTIMAL,
                    &copy_regions,
                );
            }
            let to_read = vk::ImageMemoryBarrier2::default()
                .src_stage_mask(vk::PipelineStageFlags2::COPY)
                .src_access_mask(vk::AccessFlags2::TRANSFER_WRITE)
                .dst_stage_mask(vk::PipelineStageFlags2::COMPUTE_SHADER)
                .dst_access_mask(vk::AccessFlags2::SHADER_SAMPLED_READ)
                .old_layout(vk::ImageLayout::TRANSFER_DST_OPTIMAL)
                .new_layout(vk::ImageLayout::SHADER_READ_ONLY_OPTIMAL)
                .image(image)
                .subresource_range(sub);
            device.cmd_pipeline_barrier2(
                cmd_buf,
                &vk::DependencyInfo::default()
                    .image_memory_barriers(core::slice::from_ref(&to_read)),
            );
            device
                .end_command_buffer(cmd_buf)
                .map_err(|_| "ktx2 end_command_buffer failed")?;

            *timeline_counter = timeline_counter.saturating_add(1);
            let sig_val = *timeline_counter;
            let cbi = vk::CommandBufferSubmitInfo::default().command_buffer(cmd_buf);
            let sig = vk::SemaphoreSubmitInfo::default()
                .semaphore(timeline_sem)
                .value(sig_val)
                .stage_mask(vk::PipelineStageFlags2::ALL_COMMANDS);
            let sub2 = vk::SubmitInfo2::default()
                .command_buffer_infos(core::slice::from_ref(&cbi))
                .signal_semaphore_infos(core::slice::from_ref(&sig));
            device
                .queue_submit2(queue, core::slice::from_ref(&sub2), vk::Fence::null())
                .map_err(|_| "ktx2 queue_submit2 failed")?;
            let w_info = vk::SemaphoreWaitInfo::default()
                .semaphores(core::slice::from_ref(&timeline_sem))
                .values(core::slice::from_ref(&sig_val));
            device
                .wait_semaphores(&w_info, u64::MAX)
                .map_err(|_| "ktx2 wait_semaphores failed")?;

            Self::free_buffer_slot(device, alloc, &mut staging);
            Ok(false)
        }
    }

    unsafe fn alloc_buffer_ext(
        device: &ash::Device,
        alloc: &mut Allocator,
        name: &str,
        byte_size: u64,
        location: MemoryLocation,
        base_usage: vk::BufferUsageFlags,
        enable_bda: bool,
    ) -> Result<GpuBufferSlot, &'static str> {
        let mut usage = base_usage;
        if enable_bda {
            usage |= vk::BufferUsageFlags::SHADER_DEVICE_ADDRESS;
        }
        let b_info = vk::BufferCreateInfo::default()
            .size(byte_size.max(64))
            .usage(usage)
            .sharing_mode(vk::SharingMode::EXCLUSIVE);
        // SAFETY: Standard buffer creation and `gpu_allocator` memory binding.
        unsafe {
            let buffer = device
                .create_buffer(&b_info, None)
                .map_err(|_| "create_buffer failed")?;
            let reqs = device.get_buffer_memory_requirements(buffer);
            let allocation = alloc
                .allocate(&AllocationCreateDesc {
                    name,
                    requirements: reqs,
                    location,
                    linear: true,
                    allocation_scheme: AllocationScheme::GpuAllocatorManaged,
                })
                .map_err(|_| "gpu_allocator buffer allocate failed")?;
            device
                .bind_buffer_memory(buffer, allocation.memory(), allocation.offset())
                .map_err(|_| "bind_buffer_memory failed")?;
            let device_address = if enable_bda {
                let addr_info = vk::BufferDeviceAddressInfo::default().buffer(buffer);
                device.get_buffer_device_address(&addr_info)
            } else {
                0
            };
            Ok(GpuBufferSlot {
                buffer,
                allocation: Some(allocation),
                device_address,
            })
        }
    }

    unsafe fn alloc_image_mips(
        device: &ash::Device,
        alloc: &mut Allocator,
        name: &str,
        extent_and_mips: (vk::Extent2D, u32),
        format: vk::Format,
        usage: vk::ImageUsageFlags,
        aspect: vk::ImageAspectFlags,
    ) -> Result<GpuImageSlot, &'static str> {
        let (extent, mip_levels) = extent_and_mips;
        let img_info = vk::ImageCreateInfo::default()
            .image_type(vk::ImageType::TYPE_2D)
            .format(format)
            .extent(vk::Extent3D {
                width: extent.width,
                height: extent.height,
                depth: 1,
            })
            .mip_levels(mip_levels.max(1))
            .array_layers(1)
            .samples(vk::SampleCountFlags::TYPE_1)
            .tiling(vk::ImageTiling::OPTIMAL)
            .usage(usage)
            .sharing_mode(vk::SharingMode::EXCLUSIVE)
            .initial_layout(vk::ImageLayout::UNDEFINED);
        // SAFETY: Standard image creation, `gpu_allocator` memory binding, and `VkImageView` creation.
        unsafe {
            let image = device
                .create_image(&img_info, None)
                .map_err(|_| "create_image failed")?;
            let reqs = device.get_image_memory_requirements(image);
            let allocation = match alloc.allocate(&AllocationCreateDesc {
                name,
                requirements: reqs,
                location: MemoryLocation::GpuOnly,
                linear: false,
                allocation_scheme: AllocationScheme::GpuAllocatorManaged,
            }) {
                Ok(a) => a,
                Err(_) => {
                    device.destroy_image(image, None);
                    return Err("gpu_allocator image allocate failed");
                }
            };
            if device
                .bind_image_memory(image, allocation.memory(), allocation.offset())
                .is_err()
            {
                let _ = alloc.free(allocation);
                device.destroy_image(image, None);
                return Err("bind_image_memory failed");
            }
            let view_info = vk::ImageViewCreateInfo::default()
                .image(image)
                .view_type(vk::ImageViewType::TYPE_2D)
                .format(format)
                .subresource_range(vk::ImageSubresourceRange {
                    aspect_mask: aspect,
                    base_mip_level: 0,
                    level_count: mip_levels.max(1),
                    base_array_layer: 0,
                    layer_count: 1,
                });
            let view = match device.create_image_view(&view_info, None) {
                Ok(v) => v,
                Err(_) => {
                    let _ = alloc.free(allocation);
                    device.destroy_image(image, None);
                    return Err("create_image_view failed");
                }
            };
            Ok(GpuImageSlot {
                image,
                view,
                allocation: Some(allocation),
            })
        }
    }

    unsafe fn try_init_swapchain(
        instance: &ash::Instance,
        device: &ash::Device,
        pdev_and_qf: (vk::PhysicalDevice, u32),
        surf_loader: ash::khr::surface::Instance,
        surf: vk::SurfaceKHR,
        fallback_extent: vk::Extent2D,
        enable_present_wait: bool,
    ) -> Option<SwapchainPresenter> {
        let (pdev, qf_idx) = pdev_and_qf;
        // SAFETY: Queries surface capabilities/formats and creates `VK_KHR_swapchain` if supported.
        unsafe {
            let supported = surf_loader
                .get_physical_device_surface_support(pdev, qf_idx, surf)
                .unwrap_or(false);
            if !supported {
                surf_loader.destroy_surface(surf, None);
                return None;
            }
            let Ok(caps) = surf_loader.get_physical_device_surface_capabilities(pdev, surf) else {
                surf_loader.destroy_surface(surf, None);
                return None;
            };
            let Ok(formats) = surf_loader.get_physical_device_surface_formats(pdev, surf) else {
                surf_loader.destroy_surface(surf, None);
                return None;
            };
            let Some(&chosen_fmt) = formats
                .iter()
                .find(|f| {
                    f.format == vk::Format::B8G8R8A8_UNORM || f.format == vk::Format::R8G8B8A8_UNORM
                })
                .or_else(|| formats.first())
            else {
                surf_loader.destroy_surface(surf, None);
                return None;
            };
            let extent = if caps.current_extent.width != u32::MAX && caps.current_extent.width > 0 {
                caps.current_extent
            } else {
                vk::Extent2D {
                    width: fallback_extent
                        .width
                        .clamp(caps.min_image_extent.width.max(1), caps.max_image_extent.width.max(1)),
                    height: fallback_extent
                        .height
                        .clamp(caps.min_image_extent.height.max(1), caps.max_image_extent.height.max(1)),
                }
            };
            let mut img_count = caps.min_image_count.saturating_add(1);
            if caps.max_image_count > 0 && img_count > caps.max_image_count {
                img_count = caps.max_image_count;
            }

            let sc_loader = ash::khr::swapchain::Device::new(instance, device);
            let sc_info = vk::SwapchainCreateInfoKHR::default()
                .surface(surf)
                .min_image_count(img_count)
                .image_format(chosen_fmt.format)
                .image_color_space(chosen_fmt.color_space)
                .image_extent(extent)
                .image_array_layers(1)
                .image_usage(vk::ImageUsageFlags::COLOR_ATTACHMENT | vk::ImageUsageFlags::TRANSFER_DST)
                .image_sharing_mode(vk::SharingMode::EXCLUSIVE)
                .pre_transform(caps.current_transform)
                .composite_alpha(vk::CompositeAlphaFlagsKHR::OPAQUE)
                .present_mode(vk::PresentModeKHR::FIFO)
                .clipped(true);

            let Ok(swapchain) = sc_loader.create_swapchain(&sc_info, None) else {
                surf_loader.destroy_surface(surf, None);
                return None;
            };
            let Ok(images) = sc_loader.get_swapchain_images(swapchain) else {
                sc_loader.destroy_swapchain(swapchain, None);
                surf_loader.destroy_surface(surf, None);
                return None;
            };
            let mut views = Vec::with_capacity(images.len());
            for &img in &images {
                let vi = vk::ImageViewCreateInfo::default()
                    .image(img)
                    .view_type(vk::ImageViewType::TYPE_2D)
                    .format(chosen_fmt.format)
                    .subresource_range(vk::ImageSubresourceRange {
                        aspect_mask: vk::ImageAspectFlags::COLOR,
                        base_mip_level: 0,
                        level_count: 1,
                        base_array_layer: 0,
                        layer_count: 1,
                    });
                if let Ok(v) = device.create_image_view(&vi, None) {
                    views.push(v);
                }
            }
            let sem_info = vk::SemaphoreCreateInfo::default();
            let Ok(acquire_sem) = device.create_semaphore(&sem_info, None) else {
                for v in views {
                    device.destroy_image_view(v, None);
                }
                sc_loader.destroy_swapchain(swapchain, None);
                surf_loader.destroy_surface(surf, None);
                return None;
            };
            let Ok(present_sem) = device.create_semaphore(&sem_info, None) else {
                device.destroy_semaphore(acquire_sem, None);
                for v in views {
                    device.destroy_image_view(v, None);
                }
                sc_loader.destroy_swapchain(swapchain, None);
                surf_loader.destroy_surface(surf, None);
                return None;
            };
            let present_wait_loader = if enable_present_wait {
                Some(ash::khr::present_wait::Device::new(instance, device))
            } else {
                None
            };

            Some(SwapchainPresenter {
                surface_loader: surf_loader,
                swapchain_loader: sc_loader,
                present_wait_loader,
                surface: surf,
                swapchain,
                images,
                views,
                extent,
                acquire_sem,
                present_sem,
                present_serial: 0,
            })
        }
    }

    fn write_pod_slice<T: Copy>(slot: &GpuBufferSlot, items: &[T]) -> Result<(), &'static str> {
        if items.is_empty() {
            return Ok(());
        }
        let Some(alloc) = slot.allocation.as_ref() else {
            return Err("Missing GPU buffer allocation");
        };
        let ptr = alloc
            .mapped_ptr()
            .ok_or("GPU buffer is not host-visible mapped")?;
        let byte_len = core::mem::size_of_val(items);
        if (byte_len as u64) > alloc.size() {
            return Err("Pod slice write exceeds allocated GPU buffer size");
        }
        // SAFETY: `items` is a contiguous `#[repr(C)]` `Copy` slice and `ptr` is a valid host-mapped range of size >= `byte_len`.
        unsafe {
            core::ptr::copy_nonoverlapping(
                items.as_ptr().cast::<u8>(),
                ptr.as_ptr().cast::<u8>(),
                byte_len,
            );
        }
        Ok(())
    }

    fn copy_pod_at<T: Copy>(dst_bytes: &mut [u8], byte_offset: usize, val: &T) -> Result<(), &'static str> {
        let sz = core::mem::size_of::<T>();
        let end = byte_offset.saturating_add(sz);
        let Some(slice) = dst_bytes.get_mut(byte_offset..end) else {
            return Err("Pod offset write out of mapped slice bounds");
        };
        // SAFETY: `val` is a `Copy` POD struct and `slice` has exact length `sz`.
        unsafe {
            let src = core::slice::from_raw_parts((val as *const T).cast::<u8>(), sz);
            slice.copy_from_slice(src);
        }
        Ok(())
    }

    unsafe fn free_buffer_slot(device: &ash::Device, alloc: &mut Allocator, slot: &mut GpuBufferSlot) {
        // SAFETY: Destroys `VkBuffer` and frees its backing `gpu_allocator` block after `device_wait_idle`.
        unsafe {
            if slot.buffer != vk::Buffer::null() {
                device.destroy_buffer(slot.buffer, None);
                slot.buffer = vk::Buffer::null();
            }
            if let Some(a) = slot.allocation.take() {
                let _ = alloc.free(a);
            }
        }
    }

    unsafe fn free_image_slot(device: &ash::Device, alloc: &mut Allocator, slot: &mut GpuImageSlot) {
        // SAFETY: Destroys `VkImageView`/`VkImage` and frees its `gpu_allocator` block after `device_wait_idle`.
        unsafe {
            if slot.view != vk::ImageView::null() {
                device.destroy_image_view(slot.view, None);
                slot.view = vk::ImageView::null();
            }
            if slot.image != vk::Image::null() {
                device.destroy_image(slot.image, None);
                slot.image = vk::Image::null();
            }
            if let Some(a) = slot.allocation.take() {
                let _ = alloc.free(a);
            }
        }
    }
}

impl Drop for VulkanHybridRenderer {
    fn drop(&mut self) {
        // SAFETY: Ordered Vulkan teardown:
        // 0. Join any in-flight background PSO worker thread before touching `VkDevice`,
        // 1. Wait GPU idle, 2. Release `retired_psos` & `ArcSwap` PSOs while `VkDevice` is alive,
        // 3. Free all `gpu_allocator` buffers/images & drop `Allocator` BEFORE `destroy_device`,
        // 4. Destroy sampler, swapchain/surface, synchronization/query/descriptor/pipeline objects, device, debug messenger, and instance.
        unsafe {
            if let Some(rx) = self.pso_worker_rx.take()
                && let Ok(Ok(worker_bundle)) = rx.recv()
            {
                self.device
                    .destroy_pipeline_cache(worker_bundle.worker_cache, None);
                drop(worker_bundle.pso_set);
            }

            let _ = self.device.device_wait_idle();
            self.retired_psos.clear();

            self.active_psos.store(Arc::new(CompiledPsoSet {
                device: self.device.clone(),
                use_64bit_vis_ssbo: false,
                sdf_world_pso: vk::Pipeline::null(),
                meshlet_cull_vis_pso: vk::Pipeline::null(),
                vis_indirect_gfx_pso: vk::Pipeline::null(),
                meshlet_cel_pso: vk::Pipeline::null(),
                radiance_cascades_pso: vk::Pipeline::null(),
                vfx_telegraph_pso: vk::Pipeline::null(),
                vis_fallback_gfx_pso: vk::Pipeline::null(),
                tile_shade_fallback_pso: vk::Pipeline::null(),
            }));

            let alloc_opt = match self.allocator.lock() {
                Ok(mut g) => g.take(),
                Err(poisoned) => poisoned.into_inner().take(),
            };
            if let Some(mut alloc) = alloc_opt {
                for buf in [
                    &mut self.brick_headers_buf,
                    &mut self.sdf_cells_buf,
                    &mut self.meshlets_buf,
                    &mut self.vertices_buf,
                    &mut self.indices_buf,
                    &mut self.skin_dq_buf,
                    &mut self.vis64_buf,
                    &mut self.vis_r32_fallback_buf,
                    &mut self.gbuf_shaded_buf,
                    &mut self.gbuf_normal_buf,
                    &mut self.hdr_lit_buf,
                    &mut self.hiz_mip0_buf,
                    &mut self.hiz_mip1_buf,
                    &mut self.indirect_cmds_buf,
                    &mut self.indirect_count_buf,
                    &mut self.compacted_indices_buf,
                    &mut self.scene_bda_buf,
                    &mut self.readback_buf,
                ] {
                    Self::free_buffer_slot(&self.device, &mut alloc, buf);
                }
                Self::free_image_slot(&self.device, &mut alloc, &mut self.cel_lut_img);
                Self::free_image_slot(&self.device, &mut alloc, &mut self.out_color_img);
                Self::free_image_slot(&self.device, &mut alloc, &mut self.vis_depth_img);
                if let Some(mut r_img) = self.fallback_r32_img.take() {
                    Self::free_image_slot(&self.device, &mut alloc, &mut r_img);
                }
                drop(alloc);
            }

            if self.cel_lut_sampler != vk::Sampler::null() {
                self.device.destroy_sampler(self.cel_lut_sampler, None);
            }

            if let Some(pres) = self.presenter.take() {
                self.device.destroy_semaphore(pres.acquire_sem, None);
                self.device.destroy_semaphore(pres.present_sem, None);
                for v in pres.views {
                    self.device.destroy_image_view(v, None);
                }
                pres.swapchain_loader.destroy_swapchain(pres.swapchain, None);
                pres.surface_loader.destroy_surface(pres.surface, None);
            }

            self.device.destroy_semaphore(self.timeline_sem, None);
            self.device.destroy_query_pool(self.query_pool, None);
            self.device.destroy_command_pool(self.cmd_pool, None);
            self.device.destroy_descriptor_pool(self.desc_pool, None);
            self.device.destroy_pipeline_cache(self.pipeline_cache, None);
            self.device.destroy_pipeline_layout(self.pipeline_layout, None);
            self.device.destroy_descriptor_set_layout(self.desc_set_layout, None);
            self.device.destroy_device(None);
            if let Some((dbg_loader, messenger)) = self.debug_utils.take() {
                dbg_loader.destroy_debug_utils_messenger(messenger, None);
            }
            self.instance.destroy_instance(None);
        }
    }
}

#[inline]
pub fn q32_to_f32(val: Q32) -> f32 {
    ((val.raw() as f64) / 4_294_967_296.0) as f32
}


