#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_stream_bundle_and_spirv_capability_gate() {
        let res = load_streamed_asset_bundle();
        assert_eq!(res.as_ref().err(), None);
        let Ok(bundle) = res else {
            return;
        };
        assert_eq!(bundle.meshlets.len(), 3);
        assert_eq!(bundle.skeleton_joint_count, 6);
        assert!((bundle.rest_joint_offsets[4][1]).abs() < 1e-4);
        assert!((bundle.rest_joint_offsets[5][1]).abs() < 1e-4);
        assert_eq!(bundle.cel_lut_texels.len(), 16);
        assert!(bundle.cel_lut_mips.len() >= 3);
        assert!(bundle.opus_bytes.starts_with(b"OggS"));
        assert_eq!(bundle.chunk_seeds.len(), 4);

        let full_caps = HardwareVulkanCaps {
            vulkan_minor: 4,
            shader_int64: true,
            shader_int64_atomics: true,
            buffer_device_address: true,
            host_image_copy: true,
            draw_parameters: true,
            draw_indirect_count: true,
            fragment_stores_and_atomics: true,
            sampled_image_non_uniform: true,
            dynamic_rendering_local_read: true,
            maintenance5: true,
            graphics_pipeline_library: true,
            present_wait: true,
            ray_query: false,
            mesh_shader: false,
        };
        assert!(verify_spirv_capabilities(&SPV_SDF_WORLD, &full_caps).is_ok());
        assert!(verify_spirv_capabilities(&SPV_MESHLET_CULL_VIS, &full_caps).is_ok());
        assert!(verify_spirv_capabilities(&SPV_VIS_INDIRECT_VS, &full_caps).is_ok());
        assert!(verify_spirv_capabilities(&SPV_VIS_INDIRECT_FS, &full_caps).is_ok());
        assert!(verify_spirv_capabilities(&SPV_MESHLET_CEL, &full_caps).is_ok());
        assert!(verify_spirv_capabilities(&SPV_RADIANCE_CASCADES, &full_caps).is_ok());
        assert!(verify_spirv_capabilities(&SPV_VFX_TELEGRAPH, &full_caps).is_ok());

        let fallback_caps = HardwareVulkanCaps {
            vulkan_minor: 3,
            shader_int64: false,
            shader_int64_atomics: false,
            buffer_device_address: false,
            host_image_copy: false,
            draw_parameters: true,
            draw_indirect_count: false,
            fragment_stores_and_atomics: false,
            sampled_image_non_uniform: false,
            dynamic_rendering_local_read: false,
            maintenance5: false,
            graphics_pipeline_library: false,
            present_wait: false,
            ray_query: false,
            mesh_shader: false,
        };
        assert!(verify_spirv_capabilities(&SPV_SDF_WORLD, &fallback_caps).is_err());
        assert!(verify_spirv_capabilities(&SPV_VIS_FALLBACK_VS, &fallback_caps).is_ok());
        assert!(verify_spirv_capabilities(&SPV_VIS_FALLBACK_FS, &fallback_caps).is_ok());
        assert!(verify_spirv_capabilities(&SPV_TILE_SHADE_FALLBACK, &fallback_caps).is_ok());
        assert!(verify_spirv_capabilities(&SPV_RADIANCE_CASCADES_FALLBACK, &fallback_caps).is_ok());
        assert!(verify_spirv_capabilities(&SPV_VFX_TELEGRAPH_FALLBACK, &fallback_caps).is_ok());
    }

    #[test]
    fn test_vulkan_hybrid_renderer_validation_and_async_pso_swap() {
        let res = load_streamed_asset_bundle();
        assert_eq!(res.as_ref().err(), None);
        let Ok(bundle) = res else {
            return;
        };
        let r_res = VulkanHybridRenderer::new_with_validation(None, 128, 128, &bundle, true);
        assert_eq!(r_res.as_ref().err(), None);
        let Ok(mut renderer) = r_res else {
            return;
        };

        let mut world = SparseSdfWorld::new();
        world.generate_vertical_chunk(0, 0, 1);
        world.generate_vertical_chunk(1, 0, 2);
        let staged = renderer
            .stage_dirty_sdf_bricks(&mut world, Some((1, 1)))
            .unwrap_or(0);
        assert!(staged > 0);

        let mut arena = CombatArena::new_boxed(7);
        let Some(player) = arena.spawn(
            EntityKind::Player,
            QVec3::from_ints(14, 11, 13),
            Q32::from_int(1_000),
            Q32::from_int(200),
        ) else {
            return;
        };
        let Some(boss) = arena.spawn(
            EntityKind::Boss,
            QVec3::from_ints(16, 12, 18),
            Q32::from_int(5_000),
            Q32::from_int(500),
        ) else {
            return;
        };
        arena.boss_telegraph_ticks[boss.0 as usize] = 16;
        arena.boss_pattern[boss.0 as usize] = 0;

        let motion_db = CompressedMotionDb::default();
        let mut motion = InertialMotionState::default();
        motion_db.step_combat_skeleton_q32(
            QVec3::from_ints(14, 11, 13),
            QVec3::ZERO,
            0,
            Q32::from_ratio_i32(1, 60),
            &mut motion,
        );
        motion_db.synthesize_foot_ik_world(QVec3::from_ints(14, 11, 13), &world, &mut motion);

        let cam_ov = CameraOverride {
            pos: [16.0, 12.0, 10.0],
            forward: [0.0, 0.0, 1.0],
            right: [1.0, 0.0, 1.0_f32.min(0.0)],
            up: [0.0, 1.0, 0.0],
            tan_half_fov: 0.5,
        };
        let mut rgba = vec![0_u8; 128 * 128 * 4];
        let inputs0 = HybridFrameInputs {
            arena: &arena,
            player,
            motion: &motion,
            cam_yaw_turns: Q32::ZERO,
            cam_pitch_turns: Q32::ZERO,
            camera_override: Some(cam_ov),
            time_sec_f32: 0.25,
            hitstop_flash_permille: 120,
            epoch_slot: 0,
            present_to_window: false,
        };
        assert!(renderer.render_hybrid_frame_and_readback(&inputs0, &mut rgba).is_ok());
        // Center pixel `(64, 64)` should be Dodge Amber-Gold `(255, ~148, 0)`:
        let center_off: usize = 33_024; // (64 * 128 + 64) * 4
        assert!(rgba[center_off] > 220 && rgba[center_off.saturating_add(2)] < 20);

        assert_eq!(renderer.request_async_pso_hotswap(), Ok(true));
        arena.boss_pattern[boss.0 as usize] = 1;
        let inputs1 = HybridFrameInputs {
            arena: &arena,
            player,
            motion: &motion,
            cam_yaw_turns: Q32::ZERO,
            cam_pitch_turns: Q32::ZERO,
            camera_override: Some(cam_ov),
            time_sec_f32: 0.50,
            hitstop_flash_permille: 0,
            epoch_slot: 0,
            present_to_window: false,
        };
        let mut swapped = false;
        let mut tries: u32 = 0;
        while tries < 50_000 {
            if tries < 4 {
                let _ = renderer.render_hybrid_frame_and_readback(&inputs1, &mut rgba);
            }
            if renderer.poll_async_pso_hotswap() == Ok(true) {
                let _ = renderer.render_hybrid_frame_and_readback(&inputs1, &mut rgba);
                swapped = true;
                break;
            }
            std::thread::yield_now();
            tries = tries.saturating_add(1);
        }
        assert!(swapped);
        assert!(renderer.async_pso_swaps_completed() >= 1);
        // Center pixel `(64, 64)` should now be Parry Electric-Cyan `(0, ~199, 255)`:
        assert!(rgba[center_off] < 20 && rgba[center_off.saturating_add(2)] > 220);
        assert_eq!(validation_error_count(), 0);
    }

    #[test]
    fn test_record_offscreen_frame_lossless_pixel_identity() {
        let mut raw_a = vec![0_u8; 64 * 64 * 4];
        let mut idx: usize = 0;
        while idx < 64 * 64 {
            let b = idx.saturating_mul(4);
            raw_a[b] = (idx & 0xFF) as u8;
            raw_a[b.saturating_add(1)] = ((idx >> 3) & 0xFF) as u8;
            raw_a[b.saturating_add(2)] = ((idx.wrapping_mul(17)) & 0xFF) as u8;
            raw_a[b.saturating_add(3)] = 255;
            idx = idx.saturating_add(1);
        }
        let mut runs: Vec<(u32, vk::ClearRect)> = Vec::new();
        encode_lossless_rgba_runs(64, 64, &raw_a, &mut runs);
        let mut recon = vec![0_u8; 64 * 64 * 4];
        for &(c, cr) in &runs {
            let [r, g, b, a] = rgba_u32_to_unorm_f32(c);
            let ru = (r * 255.0).round() as u8;
            let gu = (g * 255.0).round() as u8;
            let bu = (b * 255.0).round() as u8;
            let au = (a * 255.0).round() as u8;
            let x0 = cr.rect.offset.x as usize;
            let y0 = cr.rect.offset.y as usize;
            let w = cr.rect.extent.width as usize;
            let h = cr.rect.extent.height as usize;
            let mut dy: usize = 0;
            while dy < h {
                let mut dx: usize = 0;
                while dx < w {
                    let row = y0.saturating_add(dy);
                    let off = (row.saturating_mul(64).saturating_add(x0).saturating_add(dx))
                        .saturating_mul(4);
                    recon[off] = ru;
                    recon[off.saturating_add(1)] = gu;
                    recon[off.saturating_add(2)] = bu;
                    recon[off.saturating_add(3)] = au;
                    dx = dx.saturating_add(1);
                }
                dy = dy.saturating_add(1);
            }
        }
        // 100% bit-exact round-trip across arbitrary fine per-pixel gradients (`0` quantization error):
        assert_eq!(recon, raw_a);
    }
}
